// Cached-background map model: vision, fog, drawings, doors — extracted from mobile-bridge.js.

// ---------------------------------------------------------------------------
// Cached-background map model
//
// Instead of re-cropping and re-encoding a JPEG of the whole viewport on every
// token step, the client fetches the scene background art once (scene.background.get)
// and caches it keyed by a content signature (`bgVersion`). Subsequent updates are
// JSON only (scene.dynamic.get): token positions in scene-relative pixels plus a
// fog mask (global light → vision FOV; otherwise lit areas only). The client
// crops/pans the cached image locally and overlays token sprites. `bgVersion` lets the client detect when the static art
// changed and re-fetch the image; server hooks push `scene.invalidate` so other
// clients' changes (token moves, doors, walls) are reflected without polling.
// ---------------------------------------------------------------------------

export const BG_IMAGE_MIME_BY_EXT = {
  webp: "image/webp",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  bmp: "image/bmp",
  svg: "image/svg+xml",
  avif: "image/avif"
};

export function guessImageMimeFromPath(path) {
  const clean = String(path ?? "").split("?")[0].split("#")[0];
  const dot = clean.lastIndexOf(".");
  const ext = dot >= 0 ? clean.slice(dot + 1).toLowerCase() : "";
  return BG_IMAGE_MIME_BY_EXT[ext] ?? null;
}

/** Cheap, stable string hash (DJB2/xor variant) returned as base36 — used for bgVersion. */
export function hashStringToToken(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h) ^ str.charCodeAt(i);
    h |= 0;
  }
  return (h >>> 0).toString(36);
}

export function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  const CHUNK = 0x8000;
  let binary = "";
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

export function base64ToArrayBuffer(b64) {
  const binary = atob(String(b64 ?? "").trim());
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

/**
 * Sanitises a string for use as an asset-folder path segment. Dropped rather
 * than trusted: a name like "..\\..\\worlds" must not be able to climb out of
 * assets/.
 */
export function sanitizeAssetFolderName(raw, fallback) {
  const safe = String(raw ?? "").trim()
    .replace(/[\\/:*?"<>|]/g, "")
    .replace(/^\.+|\.+$/g, "")
    .replace(/\s+/g, " ")
    .slice(0, 60)
    .trim();
  return safe || fallback;
}

/** Folder name for an actor's uploaded art. */
export function actorAssetFolder(actor) {
  return sanitizeAssetFolderName(actor?.name, `actor-${actor?.id ?? "unknown"}`);
}

/**
 * Folder name for a player-authored world item's uploaded art (backgrounds,
 * races, etc. — content that has no owning actor).
 */
export function contentAssetFolder(user, contentType) {
  const owner = sanitizeAssetFolderName(user?.name, user?.id ?? "unknown");
  return `${owner}-${contentType}`;
}

/** Creates `assets/<actor>` if it is not there yet; harmless when it is. */
export async function ensureAssetFolder(FilePickerClass, folder) {
  const target = `assets/${folder}`;
  try {
    await FilePickerClass.browse("data", target);
    return target;
  } catch {
    try {
      await FilePickerClass.createDirectory("data", target, {});
    } catch (err) {
      // Two uploads racing both see "missing" and one loses; that is fine.
      const message = String(err?.message ?? err);
      if (!/exists/i.test(message)) {
        console.warn(`[${MODULE_ID}] could not create ${target}`, err);
        return "assets";
      }
    }
    return target;
  }
}

/**
 * Upload art for an actor into `Data/assets/<actor name>/` via Foundry's
 * FilePicker API, which runs on the primary GM bridge tab.
 *
 * The permission check is ours to make: the upload executes with the GM tab's
 * rights, so Foundry would happily accept it whoever asked. `FILES_UPLOAD` is
 * the same permission that decides whether the player could do this in their
 * own browser.
 */
export async function uploadActorImage(
  user,
  actor,
  imageBase64,
  mimeType,
  { requirePermission = true, maxLongSide = LOOT_IMAGE_MAX_LONG_SIDE, folderName } = {}
) {
  if (requirePermission && !userCanUploadFiles(user)) {
    throw new Error("Your Foundry role is not allowed to upload files");
  }
  if (!imageBase64 || typeof imageBase64 !== "string") return null;
  let buffer = base64ToArrayBuffer(imageBase64);
  let outMime = String(mimeType ?? "image/jpeg").trim() || "image/jpeg";
  if (buffer.byteLength === 0) throw new Error("Image payload is empty");
  if (buffer.byteLength > LOOT_IMAGE_MAX_RAW_BYTES) {
    throw new Error(`Image exceeds ${LOOT_IMAGE_MAX_RAW_BYTES} bytes`);
  }
  const downscaled = await downscaleImageBufferToDataParts(buffer, outMime, {
    maxLongSide,
    format: "jpeg",
    quality: 0.85
  });
  if (downscaled) {
    buffer = base64ToArrayBuffer(downscaled.imageBase64);
    outMime = downscaled.mimeType;
  }
  const ext = outMime.includes("png") ? "png" : "jpg";
  const file = new File(
    [buffer],
    `mobile-${foundry.utils.randomID()}.${ext}`,
    { type: outMime }
  );
  const FilePickerClass = foundry.applications?.apps?.FilePicker ?? globalThis.FilePicker;
  if (!FilePickerClass?.upload) {
    throw new Error("FilePicker.upload is unavailable in this Foundry client");
  }
  const target = await ensureAssetFolder(FilePickerClass, folderName ?? actorAssetFolder(actor));
  const response = await FilePickerClass.upload("data", target, file, {}, { notify: false });
  const path = response?.path ?? response?.target ?? null;
  if (!path || typeof path !== "string") {
    throw new Error("Image upload failed: no path returned");
  }
  return path;
}

/** Foundry's own "may this user upload art" permission. */
export function userCanUploadFiles(user) {
  try {
    if (typeof user?.can === "function") return !!user.can("FILES_UPLOAD");
    if (typeof user?.hasPermission === "function") return !!user.hasPermission("FILES_UPLOAD");
  } catch (err) {
    console.warn(`[${MODULE_ID}] FILES_UPLOAD check failed`, err);
  }
  return false;
}

// A single oversized scene image (huge map art) sent as base64 over socket.io can
// blow the mobile client's parser heap — the Android socket.io IOParser allocates the
// whole payload string on decode and throws OutOfMemoryError before app code runs.
// Anything larger than this raw-byte cap is downscaled/re-encoded before sending.
export const SCENE_IMAGE_MAX_RAW_BYTES = 8 * 1024 * 1024;
export const SCENE_IMAGE_MAX_LONG_SIDE = 2560;
export const SCENE_IMAGE_JPEG_QUALITY = 0.85;
export const SCENE_ASSET_MAX_LONG_SIDE = 1024;

/**
 * Decode an encoded image buffer and re-encode it downscaled so one socket payload
 * can never OOM the mobile client. Backgrounds are opaque (`jpeg`); token/tile assets
 * keep transparency (`png`). The mobile client maps scene coordinates via the scene
 * geometry meta and derives its own scale from the delivered bitmap size, so a lower
 * background resolution stays geometrically correct. Returns null on failure so the
 * caller can fall back.
 */
export async function downscaleImageBufferToDataParts(buffer, sourceMime, { maxLongSide, format, quality }) {
  let bitmap;
  try {
    const blob = sourceMime ? new Blob([buffer], { type: sourceMime }) : new Blob([buffer]);
    bitmap = await createImageBitmap(blob);
  } catch (e) {
    console.warn(`[${MODULE_ID}] image decode failed for downscale`, e);
    return null;
  }
  try {
    const longSide = Math.max(bitmap.width, bitmap.height) || 1;
    const scale = Math.min(1, maxLongSide / longSide);
    const outW = Math.max(1, Math.round(bitmap.width * scale));
    const outH = Math.max(1, Math.round(bitmap.height * scale));
    const canvasEl = document.createElement("canvas");
    canvasEl.width = outW;
    canvasEl.height = outH;
    canvasEl.getContext("2d").drawImage(bitmap, 0, 0, outW, outH);
    const outMime = format === "png" ? "image/png" : "image/jpeg";
    const dataUrl = outMime === "image/png"
      ? canvasEl.toDataURL(outMime)
      : canvasEl.toDataURL(outMime, quality);
    const commaIdx = dataUrl.indexOf(",");
    const imageBase64 = commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;
    return {
      imageBase64,
      mimeType: outMime,
      width: outW,
      height: outH,
      imageBytes: Math.ceil((imageBase64.length * 3) / 4)
    };
  } catch (e) {
    console.warn(`[${MODULE_ID}] image re-encode failed for downscale`, e);
    return null;
  } finally {
    bitmap.close?.();
  }
}

/**
 * Content signature of a scene's *static* background art. Changes only when the
 * cached image would actually differ (source, transform, scene dimensions, padding,
 * grid). Token / wall / light movement does NOT affect this — those are dynamic.
 */
export function sceneArtConfig(scene) {
  const level = scene?.levels?.size
    ? ((canvas?.scene?.id === scene.id ? canvas.level : null) ?? scene.initialLevel ?? scene.firstLevel)
    : null;
  if (level) {
    return {
      background: level.background ?? {},
      foregroundSrc: level.foreground?.src ?? "",
      textures: level.textures ?? {}
    };
  }

  // Foundry 12/13 store this data directly on Scene. Keeping this branch
  // isolated avoids touching v14's deprecated Scene getters.
  const background = scene?.background ?? {};
  return {
    background,
    foregroundSrc: scene?.foreground ?? "",
    textures: background
  };
}

export function computeSceneBackgroundVersion(scene) {
  if (!scene) return "none";
  const art = sceneArtConfig(scene);
  const bg = art.background;
  const textures = art.textures;
  const parts = [
    scene.id,
    bg.src ?? "",
    art.foregroundSrc,
    scene.width ?? 0,
    scene.height ?? 0,
    scene.padding ?? 0,
    scene.grid?.size ?? 0,
    scene.grid?.type ?? 0,
    textures.offsetX ?? 0,
    textures.offsetY ?? 0,
    textures.scaleX ?? 1,
    textures.scaleY ?? 1,
    textures.rotation ?? 0,
    bg.tint ?? ""
  ];
  return hashStringToToken(parts.join("|"));
}

/** Shared scene/grid metadata sent with both background and dynamic snapshots. */
export function sceneGeometryMeta(scene) {
  const grid = canvas.grid;
  const dims = canvas.dimensions;
  const sceneRect = dims?.sceneRect ?? { x: 0, y: 0 };
  return {
    sceneId: scene.id ?? null,
    sceneName: scene.name ?? null,
    bgVersion: computeSceneBackgroundVersion(scene),
    scenePixelWidth: scene.width ?? dims?.sceneWidth ?? 0,
    scenePixelHeight: scene.height ?? dims?.sceneHeight ?? 0,
    sceneRectX: Math.round(sceneRect.x),
    sceneRectY: Math.round(sceneRect.y),
    // The canvas is the background plus the scene's padding, and tokens may
    // stand anywhere in it. Without this the phone treats the artwork edge as
    // the world edge and clamps the camera short of where tokens actually are.
    canvasWidth: Math.round(dims?.width ?? scene.width ?? 0),
    canvasHeight: Math.round(dims?.height ?? scene.height ?? 0),
    gridSize: dims?.size ?? grid?.size ?? 100,
    gridSizeX: grid?.sizeX ?? grid?.size ?? 100,
    gridSizeY: grid?.sizeY ?? grid?.size ?? 100,
    gridType: detectGridType(grid, scene),
    gridTypeId: scene?.grid?.type ?? grid?.type ?? null,
    gridless: !grid || grid.isGridless
  };
}

export function normalizeDrawingShapeType(type) {
  const t = String(type ?? "polygon").toLowerCase();
  if (t === "r" || t === "rect" || t === "rectangle") return "rectangle";
  if (t === "c" || t === "circle") return "circle";
  if (t === "e" || t === "ellipse") return "ellipse";
  return "polygon";
}

export function drawingColorToClient(value) {
  if (value == null) return "#ffffff";
  if (typeof value === "string") {
    const s = value.trim();
    if (s.startsWith("#")) return s.length >= 7 ? s.slice(0, 7) : "#ffffff";
    return s;
  }
  const n = Number(value);
  if (!Number.isFinite(n)) return "#ffffff";
  return `#${Math.max(0, Math.floor(n) & 0xffffff).toString(16).padStart(6, "0")}`;
}

export function drawingShapePointsToFlat(shape) {
  const raw = shape?.points;
  if (!Array.isArray(raw) || raw.length === 0) return [];
  const first = raw[0];
  if (first != null && typeof first === "object") {
    const flat = [];
    for (const pt of raw) {
      if (Array.isArray(pt) && pt.length >= 2) {
        flat.push(Number(pt[0]), Number(pt[1]));
      } else if (pt && typeof pt === "object") {
        const x = Number(pt.x);
        const y = Number(pt.y);
        if (Number.isFinite(x) && Number.isFinite(y)) flat.push(x, y);
      }
    }
    return flat.filter((v) => Number.isFinite(v));
  }
  return raw.map((v) => Number(v)).filter((v) => Number.isFinite(v));
}

export function drawingDocsForScene(scene) {
  const fromScene = scene.drawings?.contents ?? [...(scene.drawings?.values?.() ?? [])];
  if (canvas?.ready && canvas.scene?.id === scene.id && canvas.primary?.drawings) {
    const fromCanvas = [...canvas.primary.drawings.values()]
      .map((placeable) => placeable?.document)
      .filter((doc) => doc && !doc.hidden);
    if (fromCanvas.length > 0) return fromCanvas;
  }
  return fromScene;
}

/** Scene-relative pixel geometry for client-side vector overlay (pencil/brush/shapes). */
export function drawingDocToClient(drawingDoc, sceneRectX, sceneRectY) {
  if (!drawingDoc || drawingDoc.hidden) return null;
  const shape = drawingDoc.shape ?? {};
  const points = drawingShapePointsToFlat(shape);
  return {
    drawingId: drawingDoc.id,
    x: Math.round((drawingDoc.x ?? 0) - sceneRectX),
    y: Math.round((drawingDoc.y ?? 0) - sceneRectY),
    rotation: Number(drawingDoc.rotation ?? 0),
    sort: Math.round(Number(drawingDoc.sort ?? 0)),
    strokeWidth: Number(drawingDoc.strokeWidth ?? 8),
    strokeColor: drawingColorToClient(drawingDoc.strokeColor),
    strokeAlpha: Number(drawingDoc.strokeAlpha ?? 1),
    fillType: Number(drawingDoc.fillType ?? 0),
    fillColor: drawingColorToClient(drawingDoc.fillColor),
    fillAlpha: Number(drawingDoc.fillAlpha ?? 0),
    shape: {
      type: normalizeDrawingShapeType(shape.type),
      width: Number(shape.width ?? 0),
      height: Number(shape.height ?? 0),
      radius: Number(shape.radius ?? 0),
      points
    }
  };
}

/** Cap: a token with a dozen buffs would bury the map under badges. */
export const TOKEN_STATUS_ICON_MAX = 8;

/**
 * Status icons Foundry paints on a token, taken from the actor's temporary
 * effects — the same list the canvas uses. Paths are routed like any other
 * asset so the client fetches them through `scene.asset.get` with token art.
 */
/**
 * Effects the canvas paints on a token.
 *
 * `temporaryEffects` alone is not enough: it holds only effects with a
 * duration, so a permanent status like "dead" or "bloodied" is missing from it
 * even though Foundry draws it. Walking every active effect that either is
 * temporary or carries a status id covers both.
 */
export function tokenPaintedEffects(td) {
  const actor = td.actor;
  if (!actor) return [];
  const all = actor.effects?.contents ?? [...(actor.effects?.values?.() ?? [])];
  return all.filter((e) => {
    const active = e.active ?? (!e.disabled && !e.isSuppressed);
    if (!active) return false;
    return e.isTemporary || (e.statuses?.size ?? 0) > 0;
  });
}

export function tokenStatusIcons(td) {
  const out = [];
  const seen = new Set();
  const push = (raw, name, overlay) => {
    if (!raw || typeof raw !== "string") return;
    if (seen.has(raw) || out.length >= TOKEN_STATUS_ICON_MAX) return;
    seen.add(raw);
    // Raw path, like token art: the client asks for the bytes through
    // scene.asset.get, which validates against the raw sources allowed there.
    out.push({ name: String(name ?? ""), img: raw, overlay: !!overlay });
  };

  try {
    // 1. Defeated is not an effect at all — the canvas draws it from combat
    //    state — so nothing below would ever produce the skull.
    // TokenDocument#combatant resolves this against the active encounter; doing
    // it by hand across game.combats was needlessly fragile.
    const combatant = td.combatant
      ?? game.combat?.combatants?.find?.((c) => c.tokenId === td.id)
      ?? null;
    if (combatant?.isDefeated) {
      push(CONFIG.controlIcons?.defeated ?? "icons/svg/skull.svg", "Defeated", true);
    }

    // 2. Statuses put on the TokenDocument itself, which never reach the actor.
    push(td.overlayEffect, "", true);
    for (const raw of td.effects ?? []) push(raw, "", false);

    // 3. ActiveEffects on the actor: conditions, buffs, module-applied states.
    const defeatedStatus = CONFIG.specialStatusEffects?.DEFEATED ?? "dead";
    for (const effect of tokenPaintedEffects(td)) {
      push(
        effect.img ?? effect.icon ?? null,
        effect.name,
        // Foundry paints the defeated status across the sprite even when the
        // effect itself carries no overlay flag.
        effect.getFlag?.("core", "overlay") === true ||
          (effect.statuses?.has?.(defeatedStatus) ?? false)
      );
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] token status icons failed`, err);
  }
  return out;
}

export function templateDocToClient(templateDoc, originX, originY, grid, actor = null) {
  if (!templateDoc || templateDoc.hidden) return null;
  const sceneRect = canvas.dimensions?.sceneRect ?? { x: 0, y: 0 };
  const stagingFlags = bridgeFlagsOf(templateDoc);
  const templateActorUuid = templateDoc.flags?.["midi-qol"]?.actorUuid ?? null;
  const controllable = stagingFlags.staging === true && actor?.uuid === templateActorUuid;
  // Grid-correct geometry: on v14 `templateDoc.distance` is the compat view's
  // value, converted with the default grid (wrong on any scene whose grid is
  // not 100 px / 5 ft), so measure the backing Region instead.
  const geo = templateGeometry(templateDoc, regionForTemplate(templateDoc, templateDoc.parent ?? canvas.scene), grid);
  const dist = geo.distance;
  const tt = geo.t;
  const angle = tt === "cone" ? geo.angle || Number(CONFIG?.MeasuredTemplate?.defaults?.angle) || 53.13 : 0;
  return {
    templateId: templateDoc.id,
    xInCrop: Math.round(geo.x - originX),
    yInCrop: Math.round(geo.y - originY),
    x: Math.round(geo.x - sceneRect.x),
    y: Math.round(geo.y - sceneRect.y),
    direction: geo.direction,
    shape: tt,
    distance: dist,
    elevation: templateDoc.elevation ?? 0,
    radiusPx: Math.round(geo.radiusPx),
    widthPx: Math.round(geo.widthPx),
    heightPx: Math.round(geo.heightPx),
    // `distance` in scene pixels, and the thickness of a ray. The client needs
    // both raw: the projections above lose the sign, so a rect running up-left
    // is indistinguishable from one running down-right.
    lengthPx: Math.round(geo.lengthPx),
    rayWidthPx: Math.round(geo.rayWidthPx),
    angle,
    controllable,
    itemId: controllable ? (stagingFlags.itemId ?? null) : null
  };
}

/**
 * Returns the scene background image as base64 in its original format, with the
 * geometry metadata the client needs to map scene-pixel coordinates onto it.
 * The client caches the bytes keyed by `bgVersion` and only re-fetches when it changes.
 */
export async function sceneBackgroundSnapshot(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  getOwnedActor(user, payload?.actorId);
  const scene = canvas.scene;
  const meta = sceneGeometryMeta(scene);

  const src = sceneArtConfig(scene).background.src ?? null;
  if (!src) return { ...meta, error: "no_background_src" };

  const route = foundry.utils.getRoute(src);
  const resp = await fetch(route);
  if (!resp.ok) return { ...meta, error: `fetch_failed_${resp.status}` };

  const contentType =
    resp.headers.get("content-type")?.split(";")[0]?.trim() ||
    guessImageMimeFromPath(src) ||
    "application/octet-stream";

  if (contentType.startsWith("video/")) {
    return { ...meta, error: "background_is_video" };
  }

  // Identity of the file as served, so the phone can store it next to the bytes
  // and later tell whether the same path now holds different art.
  const stamp = stampFromHeaders(resp.headers);
  const buffer = await resp.arrayBuffer();
  if (buffer.byteLength <= SCENE_IMAGE_MAX_RAW_BYTES) {
    return {
      ...meta,
      stamp,
      mimeType: contentType,
      imageBase64: arrayBufferToBase64(buffer),
      imageBytes: buffer.byteLength
    };
  }

  // Original art is large enough to OOM the mobile socket.io parser on decode.
  const downscaled = await downscaleImageBufferToDataParts(buffer, contentType, {
    maxLongSide: SCENE_IMAGE_MAX_LONG_SIDE,
    format: "jpeg",
    quality: SCENE_IMAGE_JPEG_QUALITY
  });
  if (!downscaled) {
    // No usable image: the client falls back to the (already size-capped) JPEG viewport.
    return { ...meta, error: "background_too_large" };
  }
  return {
    ...meta,
    stamp,
    mimeType: downscaled.mimeType,
    imageBase64: downscaled.imageBase64,
    imageBytes: downscaled.imageBytes,
    downscaled: true
  };
}

/**
 * `scene.background.stamp`: a cheap identity of the current scene's background
 * FILE (HEAD request, no body), so the phone can validate its on-disk copy
 * without downloading it. `stamp` is null when the server offers no ETag or
 * Last-Modified+Content-Length, or the request fails; the phone then trusts
 * bgVersion. Carries ids and opaque strings only, so any player may call it.
 */
export async function sceneBackgroundStamp(_user, _payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  const scene = canvas.scene;
  const base = { sceneId: scene.id ?? null, bgVersion: computeSceneBackgroundVersion(scene) };
  const src = sceneArtConfig(scene).background.src ?? null;
  if (!src) return buildStampReply(base);
  try {
    const resp = await fetch(foundry.utils.getRoute(src), { method: "HEAD", cache: "no-cache" });
    return buildStampReply({ ...base, stamp: resp.ok ? stampFromHeaders(resp.headers) : null });
  } catch {
    return buildStampReply(base);
  }
}

/**
 * `scene.versions`: [{ sceneId, bgVersion }] for every scene in the world. Pure
 * document data, no file access, and no need for the scene to be on the canvas;
 * the phone uses it to drop cached backgrounds of deleted or re-skinned scenes.
 */
export function sceneVersionsList(_user, _payload) {
  return { scenes: shapeSceneVersions(game.scenes?.contents ?? [], computeSceneBackgroundVersion) };
}

export const ASSET_RASTER_PX = 128;
export const ASSET_RASTER_TIMEOUT_MS = 3000;

/**
 * Renders a source the phone cannot decode into a PNG.
 *
 * The map draws sprites with Android's BitmapFactory, which reads neither SVG
 * (most core status icons, including the defeated skull) nor video (animated
 * icons some modules ship). Both are common on tokens, so the bridge — which
 * runs in a browser and can decode them — hands over a still frame instead.
 */
export async function rasterizeAssetToPng(buffer, mimeType) {
  const isVideo = String(mimeType || "").startsWith("video/");
  const blob = new Blob([buffer], { type: mimeType || "application/octet-stream" });
  const url = URL.createObjectURL(blob);
  try {
    const el = isVideo ? document.createElement("video") : new Image();
    const ready = new Promise((resolve) => {
      if (isVideo) {
        el.muted = true;
        el.playsInline = true;
        el.preload = "auto";
        // First decoded frame is available at loadeddata; seeking is unnecessary
        // and on some codecs never fires.
        el.onloadeddata = () => resolve(true);
      } else {
        el.onload = () => resolve(true);
      }
      el.onerror = () => resolve(false);
      el.src = url;
    });
    const timeout = new Promise((resolve) => setTimeout(() => resolve(false), ASSET_RASTER_TIMEOUT_MS));
    if (!(await Promise.race([ready, timeout]))) return null;

    const srcW = (isVideo ? el.videoWidth : el.naturalWidth) || ASSET_RASTER_PX;
    const srcH = (isVideo ? el.videoHeight : el.naturalHeight) || ASSET_RASTER_PX;
    const scale = Math.min(1, ASSET_RASTER_PX / Math.max(srcW, srcH));
    const outW = Math.max(1, Math.round(srcW * scale));
    const outH = Math.max(1, Math.round(srcH * scale));
    const canvasEl = document.createElement("canvas");
    canvasEl.width = outW;
    canvasEl.height = outH;
    canvasEl.getContext("2d").drawImage(el, 0, 0, outW, outH);
    const dataUrl = canvasEl.toDataURL("image/png");
    const imageBase64 = dataUrl.slice(dataUrl.indexOf(",") + 1);
    return {
      imageBase64,
      mimeType: "image/png",
      imageBytes: Math.ceil((imageBase64.length * 3) / 4)
    };
  } catch (err) {
    console.warn(`[${MODULE_ID}] asset rasterize failed`, err);
    return null;
  } finally {
    URL.revokeObjectURL(url);
  }
}

/** Image sources referenced by the current scene that a client may legitimately fetch. */
export function allowedSceneAssetSources(scene) {
  const allowed = new Set();
  const add = (s) => { if (s && typeof s === "string") allowed.add(s); };
  const art = sceneArtConfig(scene);
  add(art.background.src);
  add(art.foregroundSrc);
  // Drawn from combat state rather than from any document on the scene.
  add(CONFIG.controlIcons?.defeated ?? "icons/svg/skull.svg");
  // Door controls are drawn by the client from CONFIG, not from the wall.
  for (const icon of Object.values(doorControlIcons())) add(icon);
  // Faces in the turn order. A combatant can be off-scene or out of sight and
  // still belong in it, so these do not come from the token list above.
  for (const c of game.combats?.contents ?? []) {
    for (const combatant of c.combatants ?? []) add(combatant.img);
  }
  for (const td of scene.tokens?.contents ?? scene.tokens?.values?.() ?? []) {
    add(td.texture?.src);
    add(td.texture?.original);
    // Status icons are painted on the token, so the client legitimately needs
    // them; without this the batched fetch refuses them as off-scene sources.
    // Same three sources as tokenStatusIcons, or the ones it adds beyond
    // ActiveEffects would be requested and refused.
    add(td.overlayEffect);
    for (const raw of td.effects ?? []) add(raw);
    for (const effect of tokenPaintedEffects(td)) {
      add(effect.img ?? effect.icon ?? null);
    }
  }
  for (const tile of scene.tiles?.contents ?? scene.tiles?.values?.() ?? []) {
    add(tile.texture?.src);
  }
  return allowed;
}

/**
 * Batched image-asset fetch in original format, base64. Sources are validated
 * against what the current scene actually references so a client cannot pull
 * arbitrary files. The client caches results by `src` (token art changes rarely),
 * so each asset is sent at most once per app session.
 */
export async function sceneAssetSnapshot(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  getOwnedActor(user, payload?.actorId);
  const scene = canvas.scene;
  const requested = Array.isArray(payload?.srcs) ? payload.srcs : [];
  const allowed = allowedSceneAssetSources(scene);

  const assets = [];
  for (const src of requested) {
    if (!allowed.has(src)) {
      assets.push({ src, error: "not_on_scene" });
      continue;
    }
    const resp = await fetch(foundry.utils.getRoute(src));
    if (!resp.ok) {
      assets.push({ src, error: `fetch_failed_${resp.status}` });
      continue;
    }
    const contentType =
      resp.headers.get("content-type")?.split(";")[0]?.trim() ||
      guessImageMimeFromPath(src) ||
      "application/octet-stream";
    const buffer = await resp.arrayBuffer();
    // Neither of these survives BitmapFactory on the phone, so send a frame.
    if (contentType.startsWith("video/") || contentType.includes("svg")) {
      const raster = await rasterizeAssetToPng(buffer, contentType);
      if (!raster) {
        assets.push({ src, error: `rasterize_failed_${contentType}` });
        continue;
      }
      assets.push({ src, ...raster, rasterized: true });
      continue;
    }
    if (buffer.byteLength <= SCENE_IMAGE_MAX_RAW_BYTES) {
      assets.push({ src, mimeType: contentType, imageBase64: arrayBufferToBase64(buffer), imageBytes: buffer.byteLength });
      continue;
    }
    // Oversized asset would OOM the mobile socket.io parser; downscale keeping alpha.
    const downscaled = await downscaleImageBufferToDataParts(buffer, contentType, {
      maxLongSide: SCENE_ASSET_MAX_LONG_SIDE,
      format: "png"
    });
    if (!downscaled) {
      assets.push({ src, error: "asset_too_large" });
      continue;
    }
    assets.push({
      src,
      mimeType: downscaled.mimeType,
      imageBase64: downscaled.imageBase64,
      imageBytes: downscaled.imageBytes,
      downscaled: true
    });
  }
  return { assets };
}

/**
 * Build fog visible-regions using Foundry's PointVisionSource the same way
 * CanvasVisibility.refresh + DetectionModeLightPerception compose sight + light.
 *
 * Foundry rules (v14):
 * - PointVisionSource sweeps walls at maxR, then constrains FOV / light-perception.
 * - DetectionModeLightPerception: point visible iff in perception LOS AND
 *   EffectsCanvasGroup#testInsideLight(point).
 * - CanvasVisibility.#refreshDynamicIllumination draws GlobalLight into the vision
 *   mask using scene-wide environment.darknessLevel (not per-point regions).
 * - Light polygons must be clipped by light-perception; never emit raw light
 *   shapes (walls:false lights would otherwise punch through FoW).
 */
export function createDetachedViewerVisionSource(tokenPlaceable) {
  const VisionSourceClass = foundry?.canvas?.sources?.PointVisionSource;
  if (!VisionSourceClass || !tokenPlaceable) return null;
  if (typeof tokenPlaceable._getVisionSourceData !== "function") return null;

  const sourceId = `MobileBridge.vision.${tokenPlaceable.document?.id ?? tokenPlaceable.id}`;
  const source = new VisionSourceClass({ object: tokenPlaceable, sourceId });
  const data = tokenPlaceable._getVisionSourceData();
  // TokenDocument coerces null ranges to Infinity; if anything still yields 0/null
  // for an enabled lightPerception mode, treat it as unconstrained (maxR).
  const lp = tokenPlaceable.document?.detectionModes?.lightPerception;
  if (lp?.enabled && !(data.lightRadius > 0)) {
    data.lightRadius = canvas.dimensions?.maxR ?? data.lightRadius;
  }
  // initialize() builds los / light / shape; do NOT call add() — GM perception stays untouched.
  source.initialize(data);
  return source;
}

/**
 * Vision source bound to THIS viewer token only.
 * Prefer a live Token#vision when Foundry already built one for that token;
 * otherwise build a detached PointVisionSource (GM tab usually has no player vision).
 */
export function acquireViewerVisionSource(tokenPlaceable) {
  if (!tokenPlaceable) return { source: null, ephemeral: false };
  // Live Token#vision exists only when this token is an active vision source
  // (usually the controlled player token). On the GM tab it is usually absent.
  const live = tokenPlaceable.vision;
  if (live?.shape?.points?.length >= 6 && live?.light?.points?.length >= 6) {
    return { source: live, ephemeral: false };
  }
  return { source: createDetachedViewerVisionSource(tokenPlaceable), ephemeral: true };
}

/**
 * Whether GlobalLight contributes to the vision mask — mirrors
 * CanvasVisibility.#refreshDynamicIllumination (scene darknessLevel band).
 */
export function isGlobalLightInVisionMask() {
  const gl = canvas.environment?.globalLightSource;
  if (!gl?.active) return false;
  const { min = 0, max = 0 } = gl.data?.darkness ?? {};
  const darknessLevel = canvas.environment?.darknessLevel ?? 0;
  return darknessLevel >= min && darknessLevel <= max;
}

/**
 * Wall-bounded light-perception polygon for the viewer.
 * Prefer PointVisionSource#light (Foundry), fall back to unrestricted sight sweep.
 */
export function viewerLightPerceptionPolygon(visionSource, origin, tokenPlaceable, tokenDoc) {
  if (visionSource && !visionSource.isBlinded && visionSource.light?.points?.length >= 6) {
    return visionSource.light;
  }
  if (visionSource?.los?.points?.length >= 6) return visionSource.los;
  return computeViewerSightPolygon(origin, tokenPlaceable, tokenDoc);
}

/**
 * Intersect a light/FOV polygon with the viewer's perception (FoW).
 * Returns null when the intersection is empty — never the unclipped subject.
 */
export function clipToPerception(subject, perception) {
  if (!subject?.points?.length || subject.points.length < 6) return null;
  if (!perception?.points?.length || perception.points.length < 6) return null;
  if (typeof subject.intersectPolygon !== "function") {
    // Without Clipper, only accept subjects whose origin lies in perception —
    // still better than leaking walls:false lights through FoW.
    const ox = subject.origin?.x ?? subject.points[0];
    const oy = subject.origin?.y ?? subject.points[1];
    if (Number.isFinite(ox) && Number.isFinite(oy) && perception.contains?.(ox, oy)) {
      return subject;
    }
    return null;
  }
  const clipped = subject.intersectPolygon(perception);
  return clipped?.points?.length >= 6 ? clipped : null;
}

/**
 * Non-global light shapes for fog holes.
 * Matches CanvasVisibility (hasActiveLayer) and testInsideLight (active).
 */
export function collectActiveLightPolygons() {
  const out = [];
  const lights = canvas.effects?.lightSources;
  if (!lights) return out;
  const GlobalLight = foundry?.canvas?.sources?.GlobalLightSource ?? null;
  const list = typeof lights.values === "function" ? [...lights.values()] : [...lights];
  for (const lightSource of list) {
    if (!lightSource || typeof lightSource !== "object") continue;
    if (GlobalLight && lightSource instanceof GlobalLight) continue;
    if (lightSource.sourceType === "GlobalLight") continue;
    if (lightSource.data?.disabled) continue;
    if (!lightSource.active && !lightSource.hasActiveLayer) continue;
    const shape = lightSource.shape;
    if (!shape?.points?.length || shape.points.length < 6) continue;
    out.push({ lightSource, shape });
  }
  return out;
}

/**
 * Visible lit regions = each active light ∩ viewer light-perception.
 * Matches DetectionModeLightPerception (_testLOS + testInsideLight) as polygons.
 */
export function collectPerceivedLightPolygons(visionSource, perception) {
  const out = [];
  if (!perception?.points?.length) return out;

  for (const { lightSource, shape } of collectActiveLightPolygons()) {
    const clipped = clipToPerception(shape, perception);
    if (clipped) out.push(clipped);
    else if (lightSource.data?.vision === true) {
      // Vision-providing lights are drawn into vision.light.mask in CanvasVisibility;
      // still clip so they cannot open FoW beyond walls.
      const viaLos = clipToPerception(shape, visionSource?.los ?? perception);
      if (viaLos) out.push(viaLos);
    }
  }
  return out;
}

export function polygonPointsToClient(poly, sceneRect) {
  const raw = poly?.points;
  if (!raw?.length) return null;
  const points = new Array(raw.length);
  for (let k = 0; k < raw.length; k += 2) {
    points[k] = Math.round(raw[k] - sceneRect.x);
    points[k + 1] = Math.round(raw[k + 1] - sceneRect.y);
  }
  return points;
}

export function fogMaskFromPolygons(polygons, origin, sceneRect) {
  const originX = Math.round(origin.x - sceneRect.x);
  const originY = Math.round(origin.y - sceneRect.y);
  const clientPolys = polygons
    .map((p) => polygonPointsToClient(p, sceneRect))
    .filter((p) => p && p.length >= 6);
  if (!clientPolys.length) {
    return { points: [], holes: [], originX, originY };
  }
  return {
    points: clientPolys[0],
    holes: clientPolys.slice(1),
    originX,
    originY
  };
}

/**
 * Fog mask for the mobile map (bright background art → near-black outside holes).
 * Always scoped to the viewer token's PointVisionSource / light-perception — never
 * canvas.visibility.testVisibility (that returns GM-wide true when no vision sources
 * are active on the GM tab).
 */
export function buildViewerFogMask(origin, tokenPlaceable, tokenDoc, sceneRect) {
  if (!origin) return null;

  // Scenes without token vision: no fog overlay.
  if (canvas.visibility && canvas.visibility.tokenVision === false) return null;

  let acquired = { source: null, ephemeral: false };
  try {
    acquired = acquireViewerVisionSource(tokenPlaceable);
    const visionSource = acquired.source;
    const perception = viewerLightPerceptionPolygon(
      visionSource, origin, tokenPlaceable, tokenDoc
    );
    const globalLit = isGlobalLightInVisionMask();

    // Cannot build FoW → full fog (safe). Never skip the overlay (that = GM view).
    if (!perception?.points?.length) {
      return fogMaskFromPolygons([], origin, sceneRect);
    }

    // Global light in the vision mask → visible = this token's perception/FOV.
    if (globalLit) {
      const fov = visionSource?.shape?.points?.length >= 6
        ? visionSource.shape
        : perception;
      return fogMaskFromPolygons([fov], origin, sceneRect);
    }

    // Local lights present → lit holes only (light ∩ perception).
    const lights = collectPerceivedLightPolygons(visionSource, perception);
    if (lights.length) {
      return fogMaskFromPolygons(lights, origin, sceneRect);
    }

    // No local lights and no global light (wine_cellar: placeables=0, global disabled).
    // Foundry still draws vision.sight FOV into the vision mask — punch perception/FOV
    // so the phone isn't solid black while the GM JPEG is fully visible in-LOS.
    const fov = visionSource?.shape?.points?.length >= 6
      ? visionSource.shape
      : perception;
    return fogMaskFromPolygons([fov], origin, sceneRect);
  } finally {
    if (acquired.ephemeral) acquired.source?.destroy?.();
  }
}

/** Wall-LOS helpers / token filtering fallbacks */
export function computeViewerSightPolygon(origin, tokenPlaceable = null, tokenDoc = null) {
  const backend = CONFIG?.Canvas?.polygonBackends?.sight;
  if (!backend?.create) return null;

  // Foundry PointVisionSource sweeps at maxR, then constrains — match that.
  const maxR = canvas.dimensions?.maxR ?? 0;
  const doc = tokenPlaceable?.document ?? tokenDoc;
  const sight = doc?.sight ?? null;
  if (sight?.enabled === false) {
    const r = 0.5;
    return new PIXI.Polygon([
      origin.x, origin.y - r,
      origin.x + r, origin.y + r,
      origin.x - r, origin.y + r
    ]);
  }

  let angle = Number(sight?.angle);
  if (!Number.isFinite(angle) || angle <= 0) angle = 360;
  const rotation = Number(doc?.rotation) || 0;

  const poly = backend.create(
    { x: origin.x, y: origin.y },
    { type: "sight", radius: maxR, angle, rotation, source: tokenPlaceable || undefined }
  );
  return poly?.points?.length ? poly : null;
}

export function sightRadiusPxFromTokenDocument(td) {
  const maxR = canvas.dimensions?.maxR ?? 0;
  const sight = td?.sight;
  if (!sight || sight.enabled === false) return 0;
  if (sight.range == null) return maxR;
  const range = Number(sight.range);
  if (!Number.isFinite(range) || range < 0) return maxR;
  if (range === 0) return 0;
  const size = canvas.grid?.size ?? canvas.dimensions?.size ?? 100;
  const distance = canvas.dimensions?.distance ?? canvas.grid?.distance ?? 5;
  const unitsToPx = distance > 0 ? size / distance : size / 5;
  const externalPad = ((td.width ?? 1) * (canvas.grid?.sizeX ?? size)) / 2;
  return range * unitsToPx + externalPad;
}

/** Serialize a sight polygon to scene-relative pixels for the client fog mask. */
export function sightPolygonToClient(poly, origin, sceneRect) {
  const points = polygonPointsToClient(poly, sceneRect);
  if (!points) return null;
  return {
    points,
    holes: [],
    originX: Math.round(origin.x - sceneRect.x),
    originY: Math.round(origin.y - sceneRect.y)
  };
}

/**
 * Token visible to the viewer if its center or any inset corner falls inside the
 * pre-computed sight polygon (point-in-polygon, cheap).
 */
export function isTokenVisibleByPolygon(poly, td, sizeX, sizeY) {
  if (!poly) return true;
  const w = (td.width ?? 1) * sizeX;
  const h = (td.height ?? 1) * sizeY;
  const inset = 0.25;
  const samples = [
    [td.x + w / 2, td.y + h / 2],
    [td.x + w * inset, td.y + h * inset],
    [td.x + w * (1 - inset), td.y + h * inset],
    [td.x + w * inset, td.y + h * (1 - inset)],
    [td.x + w * (1 - inset), td.y + h * (1 - inset)]
  ];
  for (const [px, py] of samples) {
    if (poly.contains(px, py)) return true;
  }
  return false;
}

export function isTokenVisibleToViewer(td, sizeX, sizeY, wallLos, globalLit, lightShapes) {
  if (globalLit) {
    return !wallLos || isTokenVisibleByPolygon(wallLos, td, sizeX, sizeY);
  }
  if (wallLos && !isTokenVisibleByPolygon(wallLos, td, sizeX, sizeY)) return false;
  if (!lightShapes?.length) {
    // Fallback: if we couldn't resolve lights, keep tokens that pass wall LOS.
    return !wallLos || isTokenVisibleByPolygon(wallLos, td, sizeX, sizeY);
  }
  for (const shape of lightShapes) {
    if (isTokenVisibleByPolygon(shape, td, sizeX, sizeY)) return true;
  }
  return false;
}

/* ------------------------------------------------------------------ *
 * Doors
 * ------------------------------------------------------------------ */

/** How large a door sound may be before we decline to send it to a phone. */
export const DOOR_SOUND_MAX_BYTES = 1024 * 1024;

/** The control icons Foundry draws on doors, whatever a module has set them to. */
export function doorControlIcons() {
  const icons = CONFIG.controlIcons ?? {};
  return {
    open: icons.doorOpen ?? "icons/svg/door-open-outline.svg",
    closed: icons.doorClosed ?? "icons/svg/door-closed-outline.svg",
    secret: icons.doorSecret ?? "icons/svg/door-secret-outline.svg",
    locked: icons.doorLocked ?? "icons/svg/door-locked-outline.svg"
  };
}

/**
 * Foundry's own visibility test for a door control, in our coordinates.
 *
 * The midpoint itself sits on the wall, which is the boundary of the sight
 * polygon and therefore the one point whose answer cannot be trusted. Two points
 * a few pixels either side settle it: a door is visible from whichever side the
 * viewer happens to be standing on.
 */
export function isDoorVisibleToViewer(x0, y0, x1, y1, wallLos, globalLit, lightShapes) {
  const dx = -(y1 - y0);
  const dy = x1 - x0;
  const len = Math.abs(dx) + Math.abs(dy); // Manhattan, as core does, for speed
  if (!(len > 0)) return false;
  const t = 4 / len;
  const mx = (x0 + x1) / 2;
  const my = (y0 + y1) / 2;
  return (
    isPointVisibleToViewer(mx + t * dx, my + t * dy, wallLos, globalLit, lightShapes) ||
    isPointVisibleToViewer(mx - t * dx, my - t * dy, wallLos, globalLit, lightShapes)
  );
}

/**
 * Whether the viewer can see a given door at all, as a test to run over the wall
 * list.
 *
 * With token vision switched off on the scene there is nothing to hide behind,
 * so every door is on screen. With it on and no token to look through, none is:
 * the phone is showing a fully fogged map, and doors floating on it would be the
 * one thing the player could see through the dark.
 */
export function doorVisibilityTest(vision) {
  if (canvas.visibility?.tokenVision === false) return () => true;
  if (!vision?.viewerOrigin) return () => false;
  return (x0, y0, x1, y1) =>
    isDoorVisibleToViewer(x0, y0, x1, y1, vision.wallLos, vision.globalLit, vision.lightShapes);
}

/**
 * The doors a player can see, as the browser would show them.
 *
 * Foundry draws a control icon at each door's midpoint and nothing else — the
 * wall is invisible to players — so that is all that travels. A locked door is
 * reported as closed, because the padlock is the GM's icon: a player who could
 * read it from across the room would know something their character has not
 * found out yet. Secret doors do not travel at all.
 */
export function doorsForViewer(scene, sceneRect, user, vision) {
  const types = CONST.WALL_DOOR_TYPES;
  const states = CONST.WALL_DOOR_STATES;
  const isGM = !!user.isGM;
  const icons = doorControlIcons();
  const operable = !!user.can?.("WALL_DOORS") && !(game.paused && !isGM);
  const isVisible = doorVisibilityTest(vision);
  const doors = [];
  const walls = scene.walls?.contents ?? [...(scene.walls?.values?.() ?? [])];
  for (const wall of walls) {
    if (!wall.door || wall.door === types.NONE) continue;
    if (wall.door === types.SECRET && !isGM) continue;
    const c = wall.c ?? [];
    const [x0, y0, x1, y1] = c;
    if (c.length < 4 || ![x0, y0, x1, y1].every((n) => Number.isFinite(n))) continue;
    if (!isVisible(x0, y0, x1, y1)) continue;

    const ds = isGM ? wall.ds : (wall.ds === states.LOCKED ? states.CLOSED : wall.ds);
    const open = ds === states.OPEN;
    let img = open ? icons.open : icons.closed;
    if (!open && wall.door === types.SECRET) img = icons.secret;
    if (ds === states.LOCKED) img = icons.locked;

    doors.push({
      wallId: wall.id,
      x: Math.round((x0 + x1) / 2 - sceneRect.x),
      y: Math.round((y0 + y1) / 2 - sceneRect.y),
      state: open ? "open" : "closed",
      img,
      interactive: operable
    });
  }
  return doors;
}

/**
 * The sound Foundry would play for this interaction on this door, or null when
 * it has none. Mirrors Wall#_playDoorSound, including its one fallback: a door
 * with nothing configured still rattles when its handle is tried.
 */
export function doorInteractionSound(wall, interaction) {
  const configured = CONFIG.Wall?.doorSounds?.[wall.doorSound];
  let sounds = configured?.[interaction];
  if (sounds && !Array.isArray(sounds)) sounds = [sounds];
  if (!sounds?.length) {
    if (interaction !== "test") return null;
    sounds = [CONFIG.sounds?.lock ?? "sounds/lock.wav"];
  }
  return sounds[Math.floor(Math.random() * sounds.length)] ?? null;
}

/**
 * A door sound packaged for the phone.
 *
 * The browser plays the handle rattle only for the client that tried the door,
 * so it has to travel back with the answer rather than through the world. The
 * phone keeps what it receives and names it in `have` next time, after which
 * only the path travels.
 */
export async function doorSoundPayload(src, have) {
  if (!src) return null;
  if (Array.isArray(have) && have.includes(src)) return { src, cached: true };
  try {
    const resp = await fetch(foundry.utils.getRoute(src));
    if (!resp.ok) return { src, error: `fetch_failed_${resp.status}` };
    const buffer = await resp.arrayBuffer();
    if (buffer.byteLength > DOOR_SOUND_MAX_BYTES) return { src, error: "too_large" };
    return {
      src,
      mimeType: resp.headers.get("content-type")?.split(";")[0]?.trim() || "audio/ogg",
      audioBase64: arrayBufferToBase64(buffer),
      audioBytes: buffer.byteLength
    };
  } catch (err) {
    console.warn(`[${MODULE_ID}] door sound fetch failed`, src, err);
    return { src, error: "fetch_failed" };
  }
}

/**
 * GM-only global pause toggle — the same switch as the pause button in the
 * browser's UI. `payload.paused` sets the state explicitly; omitted, it flips
 * whatever `game.paused` currently is. `broadcast: true` tells core to push the
 * new state to every connected client's `game.paused`, which is also what
 * disables doors and other paused-gated actions for players everywhere.
 */
export function toggleGamePause(user, payload) {
  if (!user.isGM) throw new Error("GM only");
  const desired = typeof payload?.paused === "boolean" ? payload.paused : !game.paused;
  game.togglePause(desired, { broadcast: true });
  return { paused: !!game.paused };
}

/**
 * Open or close a door, exactly as clicking its control in the browser does.
 *
 * A lock is never announced ahead of the attempt. The phone asks to open the
 * door like any other, and what comes back is the sound of a handle turning and
 * a door that did not move — the same thing the player would get at the table,
 * and the same thing the character learns.
 */
export async function toggleSceneDoor(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  const actor = getOwnedActor(user, payload?.actorId);
  const scene = canvas.scene;
  const types = CONST.WALL_DOOR_TYPES;
  const states = CONST.WALL_DOOR_STATES;
  const wall = scene.walls?.get?.(String(payload?.wallId ?? "")) ?? null;
  if (!wall || !wall.door || wall.door === types.NONE) return { error: "no_such_door" };
  // As far as a player is concerned a secret door is a wall, so it stays one.
  if (wall.door === types.SECRET && !user.isGM) return { error: "no_such_door" };
  if (!user.can?.("WALL_DOORS")) return { error: "not_allowed" };
  if (game.paused && !user.isGM) return { error: "paused" };

  const [x0, y0, x1, y1] = wall.c ?? [];
  const vision = viewerVisionFor(viewerTokenDocFor(actor, scene));
  if (!doorVisibilityTest(vision)(x0, y0, x1, y1)) return { error: "not_visible" };

  if (wall.ds === states.LOCKED) {
    return {
      wallId: wall.id,
      state: "closed",
      locked: true,
      sound: await doorSoundPayload(doorInteractionSound(wall, "test"), payload?.haveSounds)
    };
  }
  const next = wall.ds === states.CLOSED ? states.OPEN : states.CLOSED;
  await wall.update({ ds: next });
  return { wallId: wall.id, state: next === states.OPEN ? "open" : "closed", locked: false };
}

/**
 * The token the phone is looking through, or null when the actor has none here.
 */
export function viewerTokenDocFor(actor, scene) {
  const own = tokenDocumentsForActorOnScene(actor, scene)[0] ?? null;
  if (own) return own;
  // Same fallback as listTargetableTokens — actorId match if the helper missed.
  const contents = scene.tokens?.contents ?? [...(scene.tokens?.values?.() ?? [])];
  for (const td of contents) {
    if (td.actorId === actor.id) return td;
  }
  return null;
}

/**
 * What the viewer's token can see: where it looks from, the sight polygon walls
 * leave it, whether the scene is lit throughout, and the light shapes to clip
 * against when it is not.
 *
 * Both the map snapshot and the single-point questions asked of it — is this
 * door on screen? — come through here, so the two can never disagree about what
 * the player is looking at.
 */
export function viewerVisionFor(ownTokenDoc) {
  const grid = canvas.grid;
  const sizeX = grid.sizeX ?? grid.size;
  const sizeY = grid.sizeY ?? grid.size;
  // Prefer Foundry TokenDocument#getVisionOrigin (token-shape aware) over naive center.
  let viewerOrigin = null;
  if (ownTokenDoc) {
    const vo = ownTokenDoc.getVisionOrigin?.();
    if (vo && Number.isFinite(vo.x) && Number.isFinite(vo.y)) {
      viewerOrigin = { x: vo.x, y: vo.y, elevation: vo.elevation };
    } else {
      viewerOrigin = {
        x: ownTokenDoc.x + ((ownTokenDoc.width ?? 1) * sizeX) / 2,
        y: ownTokenDoc.y + ((ownTokenDoc.height ?? 1) * sizeY) / 2,
        elevation: ownTokenDoc.elevation ?? 0
      };
    }
  }
  const viewerToken = resolveTokenPlaceable(ownTokenDoc);
  const wallLos = viewerOrigin
    ? computeViewerSightPolygon(viewerOrigin, viewerToken, ownTokenDoc)
    : null;
  const globalLit = isGlobalLightInVisionMask();
  // Light shapes for filtering — same clip as fog (light ∩ this token's perception).
  let lightShapes = [];
  if (!globalLit && viewerOrigin) {
    let acquired = { source: null, ephemeral: false };
    try {
      acquired = acquireViewerVisionSource(viewerToken);
      const perception = viewerLightPerceptionPolygon(
        acquired.source, viewerOrigin, viewerToken, ownTokenDoc
      );
      lightShapes = collectPerceivedLightPolygons(acquired.source, perception);
    } finally {
      if (acquired.ephemeral) acquired.source?.destroy?.();
    }
  }
  return { viewerOrigin, viewerToken, wallLos, globalLit, lightShapes };
}

/* ------------------------------------------------------------------ *
 * Drawing on the map
 * ------------------------------------------------------------------ */

/** A stroke longer than this is a stuck finger, not a drawing. */
export const DRAWING_MAX_POINTS = 2000;

/**
 * Turn a stroke from a phone into a Drawing everyone can see.
 *
 * Created here rather than by the player's own client, which has to exist
 * somewhere: a phone has no Foundry client of its own to create documents with.
 * That does not make it a way around the world's own rule, so the same
 * permission is asked for — DRAWING_CREATE, which Foundry gives to Trusted and
 * above and a GM may hand out or take back. Asking the permission rather than
 * the role means a world that has opened drawing to everyone opens it here too.
 *
 * The document is authored to the player who drew it and takes their user
 * colour, so the table can tell whose line it is and the GM can remove it by
 * hand like any other.
 *
 * A freehand line is a polygon with no fill and its ends apart, which is
 * exactly what Foundry's own freehand tool produces: `isClosed` is decided by
 * the fill and by whether the last point returns to the first, so leaving both
 * alone gives an open, smoothed path in the browser and in the app.
 */
export async function createSceneDrawing(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  getOwnedActor(user, payload?.actorId);
  if (!user.hasPermission?.("DRAWING_CREATE")) return { error: "not_allowed" };
  const scene = canvas.scene;
  const raw = Array.isArray(payload?.points) ? payload.points : [];
  if (raw.length < 4 || raw.length % 2 !== 0) return { error: "not_a_stroke" };
  if (raw.length > DRAWING_MAX_POINTS * 2) return { error: "too_many_points" };

  const rect = canvas.dimensions.sceneRect;
  const xs = [];
  const ys = [];
  for (let i = 0; i < raw.length; i += 2) {
    const x = Number(raw[i]);
    const y = Number(raw[i + 1]);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return { error: "bad_point" };
    xs.push(x + rect.x);
    ys.push(y + rect.y);
  }
  // Points are stored relative to the drawing's own origin, so the origin is
  // the corner of what was drawn.
  const originX = Math.min(...xs);
  const originY = Math.min(...ys);
  const points = [];
  for (let i = 0; i < xs.length; i++) {
    points.push(Math.round(xs[i] - originX), Math.round(ys[i] - originY));
  }

  const width = Math.max(...xs) - originX;
  const height = Math.max(...ys) - originY;
  const strokeWidth = Math.min(Math.max(Math.round(Number(payload?.strokeWidth) || 8), 1), 64);
  // The player's own colour is the default, not the rule: a phone can ask for
  // another. Anything that is not a plain hex triple is ignored rather than
  // passed on — this string ends up in a document the whole table renders.
  const asked = String(payload?.strokeColor ?? "");
  const strokeColor = /^#[0-9a-fA-F]{6}$/.test(asked)
    ? asked
    : (user.color?.css ?? user.color ?? "#ffffff");

  const [doc] = await scene.createEmbeddedDocuments("Drawing", [{
    author: user.id,
    x: Math.round(originX),
    y: Math.round(originY),
    shape: { type: "p", width: Math.round(width), height: Math.round(height), points },
    // Foundry's own freehand smoothing, at its maximum: a finger samples a
    // coarser line than a mouse does, and the corners show.
    bezierFactor: 0.5,
    fillType: CONST.DRAWING_FILL_TYPES.NONE,
    strokeWidth,
    strokeColor,
    strokeAlpha: 1
  }]);

  return { drawingId: doc?.id ?? null };
}

/**
 * Forward every ping drawn on this client to the phones.
 *
 * Hooked at `handlePing` rather than at the socket, because that is the one
 * place all of them meet: a ping made in this tab never comes back over the
 * socket, so a socket listener would miss exactly the GM's own — the ones most
 * worth seeing. Every client runs this method for local and remote pings alike.
 *
 * Patched on the prototype so it survives the canvas being torn down and
 * rebuilt between scenes, and guarded so a reload does not stack wrappers.
 */
export function watchPingsForPhones() {
  const layer = canvas?.controls;
  const proto = layer?.constructor?.prototype;
  if (!proto || proto.__mobileBridgePingWatched) return;
  const original = proto.handlePing;
  if (typeof original !== "function") return;
  proto.handlePing = function (user, position, data) {
    try {
      forwardPingToPhones(user, position, data);
    } catch (err) {
      console.warn(`[${MODULE_ID}] could not forward a ping`, err);
    }
    return original.call(this, user, position, data);
  };
  proto.__mobileBridgePingWatched = true;
}

/** One ping, in the coordinates and the colour the phone draws with. */
export function forwardPingToPhones(user, position, data) {
  if (!game.socket || !isPrimaryActiveGm()) return;
  if (!canvas?.ready || !canvas.scene) return;
  if (!position) return;
  // Pings belong to a scene; a phone looking at another one has no place to
  // put them.
  if (data?.scene && data.scene !== canvas.scene.id) return;
  const rect = canvas.dimensions.sceneRect;
  const payload = {
    x: Math.round(position.x - rect.x),
    y: Math.round(position.y - rect.y),
    color: user?.color?.css ?? user?.color ?? "#ffffff",
    userId: user?.id ?? null,
    userName: user?.name ?? ""
  };
  for (const other of game.users) {
    if (other.id === game.user?.id) continue;
    // The user who pinged has already seen it — in their own browser, or as the
    // echo their phone drew the moment they pressed.
    if (other.id === user?.id) continue;
    game.socket.emit(SOCKET_NAME, {
      event: "scene.ping",
      payload,
      meta: { targetUserId: other.id }
    });
  }
}

/**
 * Ping the map, as the player rather than as the tab that ran it.
 *
 * `canvas.ping()` broadcasts the activity of whoever is logged in on this
 * client, so calling it here would put the GM's name and colour on a mark the
 * player made. The broadcast underneath it is one socket event carrying a user
 * id, so sending that directly attributes the ping correctly — every other
 * client resolves the id and draws it in that player's colour, exactly as if
 * they had long-pressed the canvas themselves.
 *
 * The emitting tab has to draw it too: the event reaches everyone else, not the
 * sender.
 */
export async function pingScene(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  const actor = getOwnedActor(user, payload?.actorId);
  const scene = canvas.scene;
  const grid = canvas.grid;
  let x;
  let y;
  const tokenId = String(payload?.tokenId ?? "");
  if (tokenId) {
    const td = scene.tokens?.get?.(tokenId) ?? null;
    if (!td) return { error: "no_such_token" };
    const center = td.object?.center ?? null;
    if (center) {
      x = center.x;
      y = center.y;
    } else {
      x = td.x + ((td.width ?? 1) * (grid.sizeX ?? grid.size)) / 2;
      y = td.y + ((td.height ?? 1) * (grid.sizeY ?? grid.size)) / 2;
    }
  } else {
    const rect = canvas.dimensions.sceneRect;
    x = Number(payload?.x) + rect.x;
    y = Number(payload?.y) + rect.y;
  }
  if (!Number.isFinite(x) || !Number.isFinite(y)) return { error: "bad_point" };
  // Core refuses a ping outside the canvas, and so does this.
  if (!canvas.dimensions.rect.contains(x, y)) return { error: "off_canvas" };

  const ping = {
    scene: scene.id,
    style: CONFIG.Canvas?.pings?.types?.PULSE ?? "pulse",
    pull: false,
    zoom: canvas.stage?.scale?.x ?? 1
  };
  const origin = { x: Math.round(x), y: Math.round(y) };
  game.socket.emit("userActivity", user.id, { cursor: origin, ping });
  await canvas.controls?.handlePing?.(user, origin, ping);
  return { pinged: true, x: origin.x, y: origin.y };
}

/**
 * Remove a drawing this player made.
 *
 * Their own only. A stroke is easy to start by accident on a touch screen, so
 * taking one back has to be possible — but the map is shared, and nobody's
 * mistake is a licence to erase the GM's annotations.
 */
export async function deleteSceneDrawing(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  getOwnedActor(user, payload?.actorId);
  const scene = canvas.scene;
  const id = String(payload?.drawingId ?? "");
  const doc = scene.drawings?.get?.(id) ?? null;
  if (!doc) return { error: "no_such_drawing" };
  const authorId = doc.author?.id ?? doc.author ?? null;
  if (!user.isGM && authorId !== user.id) return { error: "not_yours" };
  await scene.deleteEmbeddedDocuments("Drawing", [id]);
  return { drawingId: id, deleted: true };
}

/** The drawings this player made on this scene, newest last. */
export function ownDrawingIds(user, scene) {
  const docs = scene.drawings?.contents ?? [...(scene.drawings?.values?.() ?? [])];
  return docs
    .filter((d) => (d.author?.id ?? d.author) === user.id)
    .map((d) => d.id);
}

/**
 * The tokens on the scene the viewer actually has on their map.
 *
 * Their own and their targets always; anything else only when vision and light
 * allow it, and nothing the GM has hidden. This is the list the phone draws, so
 * it is also the list that may block a route: a creature the player cannot see
 * blocks nothing in the browser either, and a grid that routed around one would
 * be pointing at it.
 */
export function visibleTokenDocsFor(user, scene, ownTokenId, vision) {
  const grid = canvas.grid;
  const sizeX = grid.sizeX ?? grid.size;
  const sizeY = grid.sizeY ?? grid.size;
  const userTargetIds = userTargetIdSet(user);
  const out = [];
  for (const td of scene.tokens?.contents ?? [...(scene.tokens?.values?.() ?? [])]) {
    if (td.hidden) continue;
    const owns = td.id === ownTokenId || (td.actor?.testUserPermission?.(user, "OWNER") ?? false);
    if (
      owns ||
      userTargetIds.has(td.id) ||
      isTokenVisibleToViewer(td, sizeX, sizeY, vision.wallLos, vision.globalLit, vision.lightShapes)
    ) {
      out.push(td);
    }
  }
  return out;
}

/**
 * Whether one point is visible to the viewer, on the same terms as
 * {@link isTokenVisibleToViewer}: inside the sight polygon, and lit unless the
 * scene is globally illuminated.
 */
export function isPointVisibleToViewer(x, y, wallLos, globalLit, lightShapes) {
  if (wallLos && !wallLos.contains(x, y)) return false;
  if (globalLit || !lightShapes?.length) return true;
  for (const shape of lightShapes) {
    if (shape.contains(x, y)) return true;
  }
  return false;
}

/**
 * JSON-only scene state for the cached-background model: visible tokens (in
 * scene-relative pixels), the viewer's line-of-sight polygon, combat state and
 * any active template. No image is encoded here.
 */
export function sceneDynamicSnapshot(user, payload) {
  if (!canvas?.ready || !canvas.scene) return { error: "canvas_not_ready" };
  const actor = getOwnedActor(user, payload?.actorId);
  const scene = canvas.scene;
  const grid = canvas.grid;
  const meta = sceneGeometryMeta(scene);
  if (meta.gridless) return { ...meta, error: "gridless" };

  const dims = canvas.dimensions;
  const sceneRect = dims.sceneRect;

  const ownTokenDoc = viewerTokenDocFor(actor, scene);
  const ownTokenId = ownTokenDoc?.id ?? null;
  const ownPos = ownTokenDoc ? { x: ownTokenDoc.x, y: ownTokenDoc.y } : null;
  const userTargetIds = userTargetIdSet(user);

  const vision = viewerVisionFor(ownTokenDoc);
  // Token-scoped fog. If the actor has no token on the scene, send empty mask
  // (full fog) rather than null — null skips the overlay and looks like GM vision.
  // Whether this view is vision-limited at all: the same test the branches below
  // and buildViewerFogMask use for "is there fog". The phone holds the map back
  // until `los` arrives when this is true, so `los` is guaranteed non-null then.
  const visionEnabled = canvas.visibility?.tokenVision !== false;
  let los = null;
  if (vision.viewerOrigin) {
    los = buildViewerFogMask(
      vision.viewerOrigin, resolveTokenPlaceable(ownTokenDoc), ownTokenDoc, sceneRect
    );
  }
  if (!los && visionEnabled) {
    los = {
      points: [],
      holes: [],
      originX: 0,
      originY: 0
    };
  }

  const tokens = [];
  const visibleTokenDocs = visibleTokenDocsFor(user, scene, ownTokenId, vision);
  for (const td of visibleTokenDocs) {
    const isSelf = td.id === ownTokenId;
    const isTarget = userTargetIds.has(td.id);
    const off = grid.getOffset({ x: td.x, y: td.y });
    let distanceFt = null;
    if (isSelf) {
      distanceFt = 0;
    } else if (ownPos) {
      const pathDist = canvas.grid.measurePath([ownPos, { x: td.x, y: td.y }]).distance;
      distanceFt = typeof pathDist === "number" ? Math.round(pathDist) : null;
    }

    const disp = td.disposition;
    let side = "neutral";
    if (isSelf) side = "self";
    else if (disp === CONST.TOKEN_DISPOSITIONS.FRIENDLY) side = "friendly";
    else if (disp === CONST.TOKEN_DISPOSITIONS.HOSTILE) side = "hostile";

    tokens.push({
      tokenId: td.id,
      name: td.name ?? "Unknown",
      side,
      gridI: off.i,
      gridJ: off.j,
      x: Math.round(td.x - sceneRect.x),
      y: Math.round(td.y - sceneRect.y),
      widthCells: Number(td.width ?? 1),
      heightCells: Number(td.height ?? 1),
      disposition: typeof disp === "number" ? disp : 0,
      isSelf,
      isTarget,
      distanceFt,
      elevation: td.elevation ?? 0,
      rotation: Number(td.rotation ?? 0),
      img: td.texture?.src ?? td.texture?.original ?? null,
      statuses: tokenStatusIcons(td)
    });
  }

  const self = ownTokenDoc
    ? {
        tokenId: ownTokenDoc.id,
        x: Math.round(ownTokenDoc.x - sceneRect.x),
        y: Math.round(ownTokenDoc.y - sceneRect.y),
        gridI: grid.getOffset({ x: ownTokenDoc.x, y: ownTokenDoc.y }).i,
        gridJ: grid.getOffset({ x: ownTokenDoc.x, y: ownTokenDoc.y }).j,
        widthCells: Number(ownTokenDoc.width ?? 1),
        heightCells: Number(ownTokenDoc.height ?? 1)
      }
    : null;

  const templateDocs = scene.templates?.contents ?? [...(scene.templates?.values?.() ?? [])];
  const templates = templateDocs
    .map((tdoc) => templateDocToClient(tdoc, sceneRect.x, sceneRect.y, grid, actor))
    .filter(Boolean);

  const drawingDocs = drawingDocsForScene(scene);
  const drawings = drawingDocs
    .map((dd) => drawingDocToClient(dd, sceneRect.x, sceneRect.y))
    .filter(Boolean)
    .sort((a, b) => (a.sort ?? 0) - (b.sort ?? 0));

  return {
    ...meta,
    self,
    tokens,
    templates,
    drawings,
    // Global, not scene-scoped, but sent here too so a phone already polling
    // the map (pushed by scene.invalidate on pauseGame) sees it without
    // waiting for the next health.ping keep-alive.
    paused: !!game.paused,
    doors: doorsForViewer(scene, sceneRect, user, vision),
    myDrawingIds: ownDrawingIds(user, scene),
    // Whether this player may draw at all, on the world's own terms. Sent so the
    // phone can leave the pencil out rather than offer a tool that answers every
    // stroke with a refusal.
    canDraw: !!user.hasPermission?.("DRAWING_CREATE"),
    // Same idea for area-effect templates and map pings: these are canvas
    // actions tied to the current scene, so they travel with the rest of this
    // snapshot rather than the generic per-session permission map.
    canPlaceTemplate: foundryUserCan(user, "TEMPLATE_CREATE"),
    canPingCanvas: foundryUserCan(user, "PING_CANVAS"),
    // The colour this player's strokes will be given, so the phone can draw
    // one in it before the world has assigned it.
    drawColor: user.color?.css ?? user.color ?? "#ffffff",
    los,
    visionEnabled,
    combat: combatSnapshotForActor(actor, user),
    // Only when the phone is showing the grid: the flood fill is the expensive
    // part of this snapshot, and most of the time nobody is looking at it.
    pathGrid: payload?.pathGrid === true
      ? movementGridFor(ownTokenDoc, sceneRect, {
          action: payload?.pathAction,
          maxMultiplier: payload?.pathMaxMultiplier,
          visibleTokenIds: visibleTokenDocs.map((td) => td.id)
        })
      : null
  };
}

/* ------------------------------------------------------------------ *
 * Movement grid (token-path-grid)
 * ------------------------------------------------------------------ */

export const PATH_GRID_MODULE_ID = "token-path-grid";

/**
 * The movement-grid API, or null when it is unavailable.
 *
 * Three setups provide it: the standalone token-path-grid module when it is installed and active (it wins,
 * and the copy built into the bridge then stays off), the old pre-rename module while it is still active, otherwise the copy built into this module.
 *
 * Everything the phone shows for movement comes from here rather than from our
 * own arithmetic: the grid already calls Foundry's own cost, terrain and
 * collision functions, so a space it offers is a space the browser would have
 * offered, Elevation Ruler and Terrain Mapper included.
 */
export function pathGridApi() {
  const standalone = game.modules?.get?.(PATH_GRID_MODULE_ID) ?? null;
  if (standalone?.active) return standalone.api ?? null;
  // The pre-rename module, while it is still active, runs the grid and keeps ours off (see path-grid/embedded.js).
  const legacy = game.modules?.get?.(LEGACY_MODULE_ID) ?? null;
  if (legacy?.active && legacy.pathGrid) return legacy.pathGrid;
  return embeddedPathGridApi();
}

/** The options the module accepts, taken from the client payload. */
export function pathGridOptions({ action, maxMultiplier, visibleTokenIds } = {}) {
  const options = {};
  if (action) options.action = String(action);
  const mult = Number(maxMultiplier);
  if (Number.isFinite(mult) && mult > 0) options.maxMultiplier = mult;
  // Whose map the grid is for. Without it the module answers for the client
  // running the search — a GM, who sees everything the player does not.
  if (visibleTokenIds) options.visibleTokenIds = visibleTokenIds;
  return options;
}

/**
 * The reachability grid for a token, in the scene-relative pixels the client
 * uses everywhere else.
 * @returns {object|null} null when there is nothing to draw
 */
export function movementGridFor(tokenDoc, sceneRect, options = {}) {
  const api = pathGridApi();
  if (!api) return { unavailable: "module-missing", cells: [] };
  const token = tokenDoc?.object ?? null;
  if (!token) return { unavailable: "no-token", cells: [] };
  try {
    const grid = api.getGrid(token, pathGridOptions(options));
    const budget = grid.budget ?? null;
    return {
      tokenId: tokenDoc.id ?? null,
      action: grid.action ?? null,
      unavailable: grid.unavailable ?? null,
      originI: grid.origin?.i ?? 0,
      originJ: grid.origin?.j ?? 0,
      speed: Number(budget?.speed) || 0,
      used: Number(budget?.used) || 0,
      normal: Number(budget?.normal) || 0,
      total: Number(budget?.total) || 0,
      remaining: Number(budget?.remaining) || 0,
      units: budget?.units ?? "",
      cells: (grid.cells ?? []).map((cell) => ({
        i: cell.i,
        j: cell.j,
        x: Math.round(cell.x - sceneRect.x),
        y: Math.round(cell.y - sceneRect.y),
        cost: Number(cell.cost) || 0,
        dash: cell.tier === "dash",
        canStop: cell.canStop !== false,
        // The space this one is reached from. The whole predecessor tree travels
        // with the grid, so the phone can draw the route to any space without
        // asking, the way the browser draws it under the cursor.
        pi: cell.previousI ?? null,
        pj: cell.previousJ ?? null
      }))
    };
  } catch (err) {
    console.warn(`[${MODULE_ID}] movement grid failed`, err);
    return { unavailable: "error", cells: [] };
  }
}

/**
 * Walks a token to a grid space along the route token-path-grid computed.
 *
 * The module recomputes the search rather than trusting an id from the phone,
 * so a space that stopped being reachable while the player was deciding is
 * refused here instead of teleporting the token through a closed door.
 */
/**
 * Waits until a token's document sits on a grid space, or until it clearly is
 * not going to.
 *
 * A walk that gets constrained — a door that closed, a wall the route did not
 * know about — never reaches the space that was asked for, so this cannot wait
 * on arrival alone: it also gives up once the token has stopped moving.
 *
 * @param {TokenDocument} tokenDoc
 * @param {{i: number, j: number}} target
 * @param {number} [maxFrames=240]  Roughly four seconds at 60fps
 */
export async function awaitTokenAtOffset(tokenDoc, target, maxFrames = 240) {
  const grid = canvas.grid;
  const token = tokenDoc.object;
  if (token?.movementAnimationPromise) {
    try {
      await token.movementAnimationPromise;
    } catch (_err) {
      // Rejects when the walk is interrupted; the loop below settles it.
    }
  }
  let still = 0;
  let last = tokenOffset(tokenDoc, grid);
  for (let n = 0; n < maxFrames; n++) {
    const off = tokenOffset(tokenDoc, grid);
    if (offsetsEqual(off, target)) return true;
    // Six frames without moving means the walk has ended somewhere else.
    still = offsetsEqual(off, last) ? still + 1 : 0;
    if (still >= 6) return false;
    last = off;
    await waitForPresentationFrames(1);
  }
  return false;
}

export async function moveTokenToGridCell(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  const api = pathGridApi();
  if (!api) throw new Error("Movement grid is not available");

  const tokenDoc = tokenDocumentsForActorOnScene(actor, canvas.scene)[0] ?? null;
  const token = tokenDoc?.object ?? null;
  if (!token) throw new Error("No token on scene");

  const i = Math.floor(Number(payload?.i));
  const j = Math.floor(Number(payload?.j));
  if (!Number.isFinite(i) || !Number.isFinite(j)) throw new Error("i and j are required");

  // The same perspective the grid was drawn with, or a route the phone was
  // offered could be refused here by a creature the player cannot see.
  const vision = viewerVisionFor(tokenDoc);
  const options = pathGridOptions({
    action: payload?.action,
    maxMultiplier: payload?.maxMultiplier,
    visibleTokenIds: visibleTokenDocsFor(user, canvas.scene, tokenDoc.id, vision).map((td) => td.id)
  });
  const moved = await api.moveToken(token, i, j, options);

  // `move()` resolves once the walk is committed, not once it is walked: the
  // token is still crossing the room. Answering here would send the phone off
  // to refresh against a position from the middle of the route.
  //
  // Waiting on `movementAnimationPromise` alone is not enough — at this moment
  // it can still be null, the animation not yet built, and then there is
  // nothing to await and we answer just as early. So wait for the destination
  // itself, and treat the promise as the fast path when it is there.
  await awaitTokenAtOffset(tokenDoc, { i, j });

  const off = canvas.grid.getOffset({ x: tokenDoc.x, y: tokenDoc.y });
  return {
    moved: moved === true,
    tokenId: tokenDoc.id ?? null,
    gridI: off.i,
    gridJ: off.j,
    elevation: tokenDoc.elevation ?? 0
  };
}

/**
 * List all tokens on the current scene that the given actor could target.
 * Returns token id, name, disposition (friendly/neutral/hostile), and grid distance from actor's token.
 */
export function listTargetableTokens(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  if (!canvas?.ready || !canvas.scene) return { targets: [] };

  const scene = canvas.scene;
  const ownTokenDocs = tokenDocumentsForActorOnScene(actor, scene);

  // Fallback: find by actorId if tokenDocumentsForActorOnScene missed it
  let ownTokenDoc = ownTokenDocs[0] ?? null;
  if (!ownTokenDoc) {
    for (const td of scene.tokens) {
      if (td.actorId === actor.id) { ownTokenDoc = td; break; }
    }
  }
  const ownTokenId = ownTokenDoc?.id ?? null;

  const grid = canvas.grid;
  const hasGrid = grid && !grid.isGridless;

  const ownPos = ownTokenDoc ? { x: ownTokenDoc.x, y: ownTokenDoc.y } : null;
  const userTargetIds = userTargetIdSet(user);

  const targets = [];

  // Include own token first (for self-targeting: buffs, healing)
  if (ownTokenDoc) {
    targets.push({
      tokenId: ownTokenDoc.id,
      actorId: ownTokenDoc.actorId ?? null,
      name: ownTokenDoc.name ?? actor.name ?? "Self",
      side: "self",
      distanceFt: 0,
      isTarget: userTargetIds.has(ownTokenDoc.id)
    });
  } else {
    // No token on scene — add a virtual self-target
    targets.push({
      tokenId: "__self__" + actor.id,
      actorId: actor.id,
      name: actor.name ?? "Self",
      side: "self",
      distanceFt: 0,
      isTarget: false
    });
  }

  for (const td of scene.tokens) {
    if (td.id === ownTokenId) continue;
    if (td.hidden) continue;

    let distanceFt = null;
    if (hasGrid && ownPos) {
      distanceFt = canvas.grid.measurePath([ownPos, { x: td.x, y: td.y }]).distance;
      if (typeof distanceFt === "number") distanceFt = Math.round(distanceFt);
      else distanceFt = null;
    }

    const disp = td.disposition;
    let side = "neutral";
    if (disp === CONST.TOKEN_DISPOSITIONS.FRIENDLY) side = "friendly";
    else if (disp === CONST.TOKEN_DISPOSITIONS.HOSTILE) side = "hostile";

    targets.push({
      tokenId: td.id,
      actorId: td.actorId ?? null,
      name: td.name ?? "Unknown",
      side,
      distanceFt,
      isTarget: userTargetIds.has(td.id)
    });
  }

  // Sort: self first, then hostile, then by distance
  targets.sort((a, b) => {
    const order = { self: -1, hostile: 0, neutral: 1, friendly: 2 };
    const da = order[a.side] ?? 1;
    const db = order[b.side] ?? 1;
    if (da !== db) return da - db;
    if (a.distanceFt != null && b.distanceFt != null) return a.distanceFt - b.distanceFt;
    return 0;
  });

  return { targets };
}

/**
 * Apply a target set for a user on the GM canvas and broadcast to other clients.
 *
 * Mobile bridge players never open a Foundry canvas tab, so their `viewedScene` is
 * usually unset. Foundry's stock paths then drop targets:
 * - User#_onUpdateTokenTargets returns early when viewedScene !== canvas.scene.id
 * - Users#_handleUserActivity clears targets with _onUpdateTokenTargets([]) when
 *   viewedScene !== canvas.id (including our own userActivity if sceneId is omitted)
 *
 * We bypass that by pinning viewedScene to the active scene, applying Token#_updateTarget
 * directly, caching the id set on the bridge, and broadcasting userActivity with both
 * sceneId and targets so other clients apply the same set instead of clearing it.
 */
export function applyUserTokenTargets(user, targetIds) {
  if (!canvas?.ready || !user) return;
  const sceneId = canvas.scene?.id ?? null;
  const desired = new Set((targetIds ?? []).filter(Boolean));

  if (sceneId) {
    user.viewedScene = sceneId;
  }

  // Bypass viewedScene guard in User#_onUpdateTokenTargets — update tokens directly.
  for (const t of [...user.targets]) {
    if (!desired.has(t.id)) t._updateTarget(false, user);
  }
  for (const id of desired) {
    const token = canvas.tokens.get(id);
    if (token && !user.targets.has(token)) {
      token._updateTarget(true, user);
    }
  }

  setMobileUserTargetIds(user, [...desired]);

  const applied = [...user.targets].map((t) => t.id);
  console.log(
    `[${MODULE_ID}] applyUserTokenTargets user=${user.id} viewedScene=${user.viewedScene} ` +
    `scene=${sceneId} desired=[${[...desired].join(",")}] applied=[${applied.join(",")}]`
  );

  // sceneId is required: without it, GM _handleUserActivity clears targets for users
  // whose viewedScene does not match the open canvas (normal for mobile clients).
  game.socket.emit("userActivity", user.id, {
    sceneId,
    targets: [...desired]
  });
}

/**
 * Set or clear a target in Foundry for the requesting user.
 *
 * Foundry's Token.setTarget() / canvas.tokens.setTargets() always operates on
 * game.user and broadcastActivity() throws if called for another user.
 * So we replicate the mechanism manually on the GM canvas:
 *   1. Compute the new target set for the requesting user.
 *   2. Apply it via applyUserTokenTargets (bypasses User#_onUpdateTokenTargets viewedScene check).
 *   3. Emit the "userActivity" socket event so other clients see the change.
 */
export function setTokenTarget(user, actorId, targetTokenId, targeted) {
  console.log(
    `[${MODULE_ID}] setTokenTarget user=${user?.id} actorId=${actorId} ` +
    `targetTokenId=${targetTokenId} targeted=${targeted} canvasReady=${!!canvas?.ready}`
  );
  if (!actorId) throw new Error("actorId is required");
  getOwnedActor(user, actorId);

  if (!targetTokenId) throw new Error("targetTokenId is required");
  if (!canvas?.ready) throw new Error("Canvas not ready");

  const doTarget = targeted !== false;

  // Resolve the actual token ID (handle virtual __self__ prefix)
  const actualTokenId = targetTokenId.startsWith("__self__") ? null : targetTokenId;

  const tokenDoc = actualTokenId ? canvas.scene?.tokens?.get(actualTokenId) : null;
  if (!tokenDoc) throw new Error(`Target token not found on scene: ${targetTokenId}`);

  const tokenObject = tokenDoc.object ?? canvas.tokens?.get(actualTokenId) ?? null;
  if (!tokenObject) throw new Error("Target token has no canvas object");

  const beforeIds = mobileUserTargetIds(user);
  // Additive targeting: any number of tokens may be targeted at once (GM verifies legality).
  const currentIds = new Set(beforeIds);
  if (doTarget) {
    currentIds.add(actualTokenId);
  } else {
    currentIds.delete(actualTokenId);
  }

  console.log(
    `[${MODULE_ID}] setTokenTarget applying user=${user?.id} before=[${beforeIds.join(",")}] ` +
    `after=[${[...currentIds].join(",")}] token=${tokenDoc.name ?? "Unknown"}`
  );
  applyUserTokenTargets(user, [...currentIds]);

  return {
    targetTokenId: actualTokenId,
    targeted: doTarget,
    name: tokenDoc.name ?? "Unknown"
  };
}

/**
 * Use an item (weapon attack, consumable, etc.) via dnd5e item.use().
 * Posts result to Foundry chat.
 *
 * Problem: item.use() checks game.user.targets for damage application,
 * but game.user is the GM (the bridge runs on the GM tab). The requesting
 * player's targets are on `user.targets`. So we temporarily copy the
 * player's targets onto the GM before calling item.use(), then restore.
 *
 * Area spells: patch AbilityTemplate.drawPreview for a single non-interactive
 * template owned by the caster. Tag templates with dnd5e/midi-qol flags and
 * delegate targeting to Midi-QOL (selectTargetsFromTemplates / processPlacedTemplates).
 * Do not restore GM targets in finally — the async workflow still needs them.
 */

export function bridgeRuntimeState() {
  if (!game.bagOfWorlds) game.bagOfWorlds = {};
  return game.bagOfWorlds;
}

/** Bridge-side target cache: userActivity without sceneId clears user.targets on the GM client. */
export function mobileUserTargetIds(user) {
  const live = [...user.targets].map((t) => t.id);
  if (live.length) return live;
  const cached = bridgeRuntimeState().mobileUserTargets?.get(user.id);
  return cached ? [...cached] : [];
}

export function setMobileUserTargetIds(user, targetIds) {
  if (!bridgeRuntimeState().mobileUserTargets) {
    bridgeRuntimeState().mobileUserTargets = new Map();
  }
  bridgeRuntimeState().mobileUserTargets.set(user.id, [...targetIds]);
}

export function userTargetIdSet(user) {
  return new Set(mobileUserTargetIds(user));
}

export function beginItemCastSession(item) {
  bridgeRuntimeState().itemCastSession = {
    itemId: item.id,
    itemName: item.name,
    directByParent: new Map(),
    inAuraByParent: new Map()
  };
}

export function endItemCastSession() {
  if (!game.bagOfWorlds?.itemCastSession) return;
  delete game.bagOfWorlds.itemCastSession;
}

export function isDirectEffectForCastItem(effectName, session) {
  return !!effectName && effectName === session?.itemName;
}

export function isInAuraEffectForCastItem(effectName, session) {
  if (!effectName || !session?.itemName) return false;
  if (effectName === `${session.itemName} (In Aura)`) return true;
  return effectName.includes("(In Aura)") && effectName.includes(session.itemName);
}

export function parentHasDirectCastEffect(parent, session) {
  if (!parent?.effects || !session?.itemName) return false;
  return parent.effects.some((e) => !e.disabled && e.name === session.itemName);
}

export function parentHasInAuraCastEffect(parent, session) {
  if (!parent?.effects || !session?.itemName) return false;
  return parent.effects.some((e) => !e.disabled && isInAuraEffectForCastItem(e.name, session));
}

export function preCreateActiveEffectItemCastDedupe(document, data, options, userId) {
  const session = game.bagOfWorlds?.itemCastSession;
  if (!session) return;

  const effectName = data?.name ?? document?.name;
  const parent = document?.parent;
  const parentKey = parent?.uuid ?? parent?.id;
  if (!parentKey) return;

  if (isDirectEffectForCastItem(effectName, session)) {
    if (session.directByParent.has(parentKey)) {
      return false;
    }
    if (session.inAuraByParent.has(parentKey) || parentHasInAuraCastEffect(parent, session)) {
      return false;
    }
    session.directByParent.set(parentKey, effectName);
    return;
  }

  if (!isInAuraEffectForCastItem(effectName, session)) return;

  if (session.inAuraByParent.has(parentKey)) {
    return false;
  }
  if (session.directByParent.has(parentKey) || parentHasDirectCastEffect(parent, session)) {
    return false;
  }
  session.inAuraByParent.set(parentKey, effectName);
}

export function buildMobileRollEvent(advantageMode) {
  const mode = normalizeAdvantageMode(advantageMode);
  // dnd5e's D20Roll.buildPost reads `config.event.target.closest("[data-message-id]")`
  // with optional chaining only on `event` (not `event.target`). A real click event
  // has a DOM target; our programmatic event has none, so we expose a DOM-less stub
  // whose closest() returns null — dnd5e then treats it as "no originating message"
  // instead of throwing on undefined.target.closest.
  const domlessTarget = { closest: () => null, dataset: {} };
  return {
    altKey: mode === 1,
    ctrlKey: mode === -1,
    shiftKey: false,
    metaKey: false,
    target: domlessTarget,
    currentTarget: domlessTarget,
    preventDefault() {},
    stopPropagation() {}
  };
}

export function mobileItemUseAdvantageMode() {
  return bridgeRuntimeState().itemUseAdvantageMode ?? 0;
}

export function beginItemUseAdvantageMode(advantageMode) {
  const mode = normalizeAdvantageMode(advantageMode);
  bridgeRuntimeState().itemUseAdvantageMode = mode;
  rollAdvantageTraceVerbose("itemUseAdvantageMode begin", { mode });
}

export function endItemUseAdvantageMode() {
  const had = mobileItemUseAdvantageMode();
  delete bridgeRuntimeState().itemUseAdvantageMode;
  if (had !== 0) rollAdvantageTraceVerbose("itemUseAdvantageMode end", { hadMode: had });
}

export function resolveMobileAttackAdvantageMode(config) {
  const sessionMode = mobileItemUseAdvantageMode();
  if (sessionMode !== 0) return sessionMode;
  if (config?.advantage === true) return 1;
  if (config?.disadvantage === true) return -1;
  const rollOpts = config?.rolls?.[0]?.options;
  if (rollOpts?.advantage === true) return 1;
  if (rollOpts?.disadvantage === true) return -1;
  if (config?.event?.altKey) return 1;
  if (config?.event?.ctrlKey) return -1;
  return 0;
}

export function resolveMobileItemUseAdvantageMode(config) {
  const sessionMode = mobileItemUseAdvantageMode();
  if (sessionMode !== 0) return sessionMode;
  return resolveMobileAttackAdvantageMode(config);
}

export function applyMobileRollAdvantageToConfig(config, mode) {
  if (mode === 0 || !config) return;
  const opts = { advantage: mode === 1, disadvantage: mode === -1 };
  config.advantage = opts.advantage;
  config.disadvantage = opts.disadvantage;
  config.event ??= buildMobileRollEvent(mode);
  if (Array.isArray(config.rolls) && config.rolls.length) {
    for (const roll of config.rolls) {
      roll.options ??= {};
      roll.options.advantage = opts.advantage;
      roll.options.disadvantage = opts.disadvantage;
    }
  } else {
    config.rolls = [{ options: { ...opts } }, ...(Array.isArray(config.rolls) ? config.rolls : [])];
  }
  config.midiOptions ??= {};
  config.midiOptions.advantage = opts.advantage;
  config.midiOptions.disadvantage = opts.disadvantage;
}

export function applyMobileAttackRollAdvantage(config, dialog, hookName = "?") {
  if (game.modules.get("midi-qol")?.active) {
    rollAdvantageTraceVerbose("attack hook skipped (midi-qol postConfiguration path)", { hook: hookName });
    return;
  }
  const sessionMode = mobileItemUseAdvantageMode();
  const resolvedMode = resolveMobileAttackAdvantageMode(config);
  const mode = resolveMobileItemUseAdvantageMode(config);
  rollAdvantageTraceVerbose("attack hook", {
    hook: hookName,
    sessionMode,
    resolvedMode,
    mode,
    configBefore: summarizeRollConfig(config)
  });
  if (mode === 0) return;

  applyMobileRollAdvantageToConfig(config, mode);

  rollAdvantageTrace("attack hook applied", {
    hook: hookName,
    sessionMode,
    mode,
    configAfter: summarizeRollConfig(config)
  });
  if (dialog) {
    dialog.configure = false;
    dialog.configureDialog = false;
    dialog.event = buildMobileRollEvent(mode);
  }
}

/** Midi+dnd5e can leave attack rolls at 1d20 despite workflow adv flags; patch the built roll before evaluate. */
export function applyMobileAttackRollPostConfiguration(rolls) {
  const mode = mobileItemUseAdvantageMode();
  if (mode === 0 || !Array.isArray(rolls) || !rolls.length) return;
  const D20Roll = CONFIG.Dice.D20Roll;
  if (!D20Roll) return;
  const advantageMode = mode === 1 ? D20Roll.ADV_MODE.ADVANTAGE : D20Roll.ADV_MODE.DISADVANTAGE;
  let patched = false;
  for (const roll of rolls) {
    if (!(roll instanceof D20Roll)) continue;
    roll.options.advantage = mode === 1;
    roll.options.disadvantage = mode === -1;
    roll.options.advantageMode = advantageMode;
    roll.configureModifiers();
    patched = true;
  }
  if (patched) {
    rollAdvantageTrace("attack postConfiguration applied", {
      mode,
      formulas: rolls.map((r) => r.formula)
    });
  }
}

export function applyMobileAttackRollAdvantageDeprecated(_item, oldConfig) {
  const mode = mobileItemUseAdvantageMode();
  if (mode === 0 || !oldConfig) return;
  oldConfig.advantage = mode === 1;
  oldConfig.disadvantage = mode === -1;
  oldConfig.fastForward = true;
  oldConfig.event ??= buildMobileRollEvent(mode);
}

export function deferEndItemUseAdvantageMode() {
  const mode = mobileItemUseAdvantageMode();
  if (mode === 0) {
    endItemUseAdvantageMode();
    return;
  }
  const rt = bridgeRuntimeState();
  if (rt.itemUseAdvantageCleanupTimer) return;
  const finish = () => {
    if (rt.itemUseAdvantageCleanupTimer) {
      window.clearTimeout(rt.itemUseAdvantageCleanupTimer);
      delete rt.itemUseAdvantageCleanupTimer;
    }
    endItemUseAdvantageMode();
  };
  Hooks.once("dnd5e.postRollAttackV2", finish);
  Hooks.once("dnd5e.postRollAttack", finish);
  if (game.modules.get("midi-qol")?.active) {
    Hooks.once("midi-qol.RollComplete", finish);
  }
  rt.itemUseAdvantageCleanupTimer = window.setTimeout(finish, 60000);
}

export function applyMobileMidiAttackAdvantage(workflow) {
  const mode = mobileItemUseAdvantageMode();
  rollAdvantageTraceVerbose("midi preAttackRoll", { mode, workflowId: workflow?.id });
  if (mode === 0 || !workflow) return;

  const event = buildMobileRollEvent(mode);
  workflow.event = event;
  workflow.workflowOptions ??= {};
  workflow.workflowOptions.event = event;
  workflow.rollOptions ??= {};
  workflow.rollOptions.event = event;
  workflow.workflowOptions.fastForwardAttack = true;
  workflow.rollOptions.fastForwardAttack = true;

  workflow.attackAdvAttribution = new Set();
  workflow.advReminderAttackAdvAttribution = new Set();
  // Explicit mobile adv/dis must win over checkAttackAdvantage (e.g. flanking) in configureAttackRoll.
  workflow.flankingAdvantage = false;

  if (mode === 1) {
    workflow.advantage = true;
    workflow.disadvantage = false;
    workflow.workflowOptions.advantage = true;
    workflow.workflowOptions.disadvantage = false;
    workflow.rollOptions.advantage = true;
    workflow.rollOptions.disadvantage = false;
  } else {
    workflow.advantage = false;
    workflow.disadvantage = true;
    workflow.workflowOptions.advantage = false;
    workflow.workflowOptions.disadvantage = true;
    workflow.rollOptions.advantage = false;
    workflow.rollOptions.disadvantage = true;
  }
  rollAdvantageTrace("midi preAttackRoll applied", { mode, event: { altKey: event.altKey, ctrlKey: event.ctrlKey } });
}

export function registerMobileAttackRollHooks() {
  Hooks.on("dnd5e.preRollAttackV2", (config, dialog) => {
    applyMobileAttackRollAdvantage(config, dialog, "dnd5e.preRollAttackV2");
  });
  Hooks.on("dnd5e.preRollAttack", applyMobileAttackRollAdvantageDeprecated);
  Hooks.on("midi-qol.preAttackRoll", applyMobileMidiAttackAdvantage);
  Hooks.on("dnd5e.postAttackRollConfiguration", applyMobileAttackRollPostConfiguration);
  Hooks.on("dnd5e.postD20testRollConfiguration", applyMobileAttackRollPostConfiguration);
}

/**
 * ---------------------------------------------------------------------------
 * PHASE 1 — mobile save prompts (midi-qol integration). Reactions are a later
 * phase and are NOT touched here.
 *
 * Target setting: midi-qol `configSettings.playerRollSaves = "chat"`. In that
 * mode, midi-qol's own Workflow#checkSaves (midi-qol/src/module/Workflow.js,
 * ~L4983) whispers the player "please roll your save" and parks a Promise in
 * `workflow.saveRequests[<token id>]`. That Promise resolves the moment a chat
 * message *renders* whose `speaker.token` equals that token id and whose
 * `flags.dnd5e.messageType === "roll"` — see Workflow#processSaveRoll (~L5662),
 * which is hooked on `renderChatMessageHTML` only for the duration of
 * checkSaves() (Workflow.js ~L2358-2372). We deliberately do not reimplement or
 * replace any of that: we (1) push a structured prompt to the player's phone
 * alongside midi's own whisper, gated on `midi-qol.preCheckSaves` so we see the
 * save DC/ability before checkSaves() has even started, and (2) when the phone
 * answers, drive the exact same `actor.rollSavingThrow()` call midi's own
 * "roll save" chat-card button runs (activities/SaveActivity.js `#rollSave`),
 * with the speaker pinned to the token midi is waiting on. The resulting chat
 * message is what midi's own listener picks up — there is no separate "feed the
 * result into midi" API. See respondToMobileSaveRequest /
 * feedMobileSaveResponseIntoMidiWorkflow below.
 *
 * LIVE-UNKNOWN: everything above is read from midi-qol's vendored v13 source
 * (midi-qol/src/module/Workflow.js + activities/SaveActivity.js), not observed
 * against a live world — see the report for the full list.
 * ---------------------------------------------------------------------------
 */

/** requestId (== hit token id, matching midi-qol's own saveRequests key) -> pending mobile prompt context. */
export function pendingMobileSaveRequests() {
  const rt = bridgeRuntimeState();
  if (!rt.pendingMobileSaveRequests) rt.pendingMobileSaveRequests = new Map();
  return rt.pendingMobileSaveRequests;
}

// Generous compared to midi's own configSettings.playerSaveTimeout (usually
// well under a minute) — this only exists so an entry can't leak forever if a
// player never opens the app to answer (midi's own timeout will have already
// auto-rolled for them well before this fires; we just stop tracking it).
const MOBILE_SAVE_REQUEST_TTL_MS = 5 * 60 * 1000;

function prunePendingMobileSaveRequests() {
  const pending = pendingMobileSaveRequests();
  const now = Date.now();
  for (const [id, entry] of pending) {
    if (now - entry.createdAt > MOBILE_SAVE_REQUEST_TTL_MS) pending.delete(id);
  }
}

/**
 * First non-GM, currently-active Foundry user who owns this actor. The bridge
 * has no separate registry of "which users have the phone app open" (the app
 * is just a normal socket.io user session, indistinguishable from a desktop
 * browser tab — see CLAUDE.md transport section) so this active-owner check is
 * the same proxy the rest of the bridge already uses for "push it to the
 * player" (compare forwardActorHpToMobile / forwardActorConditionToMobile in
 * events.js). If nobody is home, we simply don't push — midi's own "chat" mode
 * still whispers + times out normally either way.
 */
export function activeMobileOwnerOfActor(actor) {
  // Characters only: NPC-type actors are never prompted on the phone (see savePrompt.js).
  return pickSaveRequestOwner(actor, game.users);
}

/**
 * Mirrors Workflow#checkSaves' own ability/DC resolution for the `.save` case
 * (midi-qol/src/module/Workflow.js ~L4739-4750). Must stay in lockstep with
 * that logic or the app would prompt for the wrong ability/DC. Ability checks
 * (CheckActivity / `.check`) are out of scope for Phase 1, same as reactions.
 */
export function resolveSaveActivityAbilityAndDc(saveActivity) {
  const save = saveActivity?.save;
  if (!save) return null;
  const ability = save.ability instanceof Set ? save.ability.first() : save.ability;
  const dc = Number(save.dc?.value);
  return { ability, dc: Number.isFinite(dc) ? dc : null };
}

/**
 * Hooked on `midi-qol.preCheckSaves`. Fires once per item use that has a save,
 * before Workflow#checkSaves runs (before it whispers players / opens its own
 * saveRequests). For every hit target whose actor has an active mobile-owning
 * player, push a `save.request` event and remember enough to resolve it later.
 *
 * Racing midi's own "chat" whisper is intentional and harmless: whichever the
 * player answers first (the app dialog, or — if they still have one open —
 * their desktop character sheet) resolves `workflow.saveRequests[requestId]`
 * and the other simply finds no pending entry to resolve.
 */
export function notifyMobileSaveRequests(workflow) {
  try {
    if (!game.socket || !isPrimaryActiveGm()) return;
    const info = resolveSaveActivityAbilityAndDc(workflow?.saveActivity);
    if (!info?.ability) return;

    const allHitTargets = new Set([...(workflow.hitTargets ?? []), ...(workflow.hitTargetsEC ?? [])]);
    if (!allHitTargets.size) return;

    prunePendingMobileSaveRequests();
    const pending = pendingMobileSaveRequests();
    const source = workflow.item?.name ?? workflow.activity?.name ?? "";

    for (const token of allHitTargets) {
      const actor = token?.actor;
      if (!actor) continue;
      const owner = activeMobileOwnerOfActor(actor);
      if (!owner) continue;

      const requestId = token.id ?? foundry.utils.randomID();
      pending.set(requestId, {
        actorId: actor.id,
        tokenId: token.id,
        userId: owner.id,
        ability: info.ability,
        dc: info.dc,
        workflowId: workflow.id,
        createdAt: Date.now()
      });

      game.socket.emit(SOCKET_NAME, {
        event: "save.request",
        payload: {
          saveRequestId: requestId,
          actorId: actor.id,
          tokenId: token.id,
          ability: info.ability,
          dc: info.dc,
          canAdvantage: true,
          source
        },
        meta: { targetUserId: owner.id }
      });
      bridgeTrace("save.request pushed", {
        requestId, actorId: actor.id, ability: info.ability, dc: info.dc, owner: owner.name
      });
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] notifyMobileSaveRequests failed`, err);
  }
}

export function registerMobileSaveHooks() {
  Hooks.on("midi-qol.preCheckSaves", notifyMobileSaveRequests);
}

/**
 * THE "feed the result back into midi-qol" call — isolated on purpose, since
 * this is the one piece that needs live confirmation against a running
 * midi-qol + dnd5e table (see LIVE-UNKNOWNS in the report). Mirrors
 * activities/SaveActivity.js's own `#rollSave` chat-card button handler:
 * `actor.rollSavingThrow({ability, target: dc}, {}, message)`. There is no
 * midi-qol API call here on purpose — midi exposes none for this — we only
 * need the chat message this produces to carry `speaker.token === <the token
 * id midi is waiting on>`, which is what Workflow#processSaveRoll matches on.
 *
 * Must run on the primary GM tab: the Workflow instance awaiting this save
 * lives only in that tab's memory (workflows are not replicated across
 * clients), and it's that tab's `renderChatMessageHTML` hook that needs to see
 * this message — see PRIMARY_GM_ONLY_ACTIONS in constants.js.
 */
export async function feedMobileSaveResponseIntoMidiWorkflow({ actor, tokenDocument, ability, dc, advantageMode }) {
  const config = { ability };
  if (Number.isFinite(dc)) config.target = dc;
  applyAdvantageToRollConfig(config, advantageMode, "mobileSaveRespond");

  const speaker = ChatMessage.getSpeaker({
    actor,
    token: tokenDocument ?? undefined,
    scene: tokenDocument?.parent ?? canvas?.scene ?? undefined
  });
  const message = { create: true, data: { speaker } };

  rollAdvantageTraceVerbose("feedMobileSaveResponseIntoMidiWorkflow", {
    actorId: actor?.id,
    tokenId: tokenDocument?.id,
    ability,
    dc,
    advantageMode,
    config: summarizeRollConfig(config)
  });

  return actor.rollSavingThrow(config, { configure: false }, message);
}

/**
 * `actor.save.respond` handler. Looks up the pending prompt this requestId was
 * issued for (set by notifyMobileSaveRequests), confirms the responding user is
 * still the one it was issued to (defense against a stale/spoofed requestId
 * naming someone else's actor), then rolls via
 * feedMobileSaveResponseIntoMidiWorkflow.
 *
 * If the requestId is unknown — midi's own PlayerSaveTimeout already auto-
 * rolled for them, the player answered from their desktop sheet first, or the
 * entry simply expired (MOBILE_SAVE_REQUEST_TTL_MS) — this is a no-op: midi has
 * already moved on and there is nothing left to feed a result into.
 */
export async function respondToMobileSaveRequest(user, saveRequestId, advantageMode) {
  if (!saveRequestId) throw new Error("saveRequestId is required");
  const pending = pendingMobileSaveRequests();
  const entry = pending.get(saveRequestId);
  if (!entry) {
    bridgeTrace("actor.save.respond: no pending request (already resolved/expired)", { saveRequestId });
    return { accepted: false, reason: "expired" };
  }
  if (entry.userId !== user.id) {
    throw new Error("This save request was not issued to you");
  }
  const actor = getOwnedActor(user, entry.actorId);
  pending.delete(saveRequestId);

  const tokenDocument =
    canvas?.tokens?.get(entry.tokenId)?.document
    ?? canvas?.scene?.tokens?.get(entry.tokenId)
    ?? null;

  await feedMobileSaveResponseIntoMidiWorkflow({
    actor,
    tokenDocument,
    ability: entry.ability,
    dc: entry.dc,
    advantageMode
  });

  return { accepted: true };
}

/** Matches midi-qol AttackActivity #rollAttackAdvantage / #rollAttackDisadvantage first item.use midiOptions. */
export function buildItemUseMidiOptions(advantageMode) {
  const mode = normalizeAdvantageMode(advantageMode);
  // A mobile tap can't click the MidiQoL chat-card "Attack" button, so the bridge
  // must drive the attack roll itself for every mode. Without this, a normal tap
  // falls back to the GM's gmAutoAttack setting (off by default), leaving the
  // workflow parked on an un-clickable card while advantage/disadvantage worked
  // only because they already forced these flags.
  const workflowOptions = {
    targetConfirmation: "none",
    autoRollAttack: true,
    fastForwardAttack: true
  };
  const midiOptions = { workflowOptions };
  if (mode === 1) {
    midiOptions.advantage = true;
    midiOptions.disadvantage = false;
    workflowOptions.advantage = true;
    workflowOptions.disadvantage = false;
  } else if (mode === -1) {
    midiOptions.advantage = false;
    midiOptions.disadvantage = true;
  }
  return midiOptions;
}

export function buildItemUseRollConfig(advantageMode) {
  const mode = normalizeAdvantageMode(advantageMode);
  return {
    configure: false,
    configureDialog: false,
    event: buildMobileRollEvent(mode),
    midiOptions: buildItemUseMidiOptions(mode)
  };
}

/**
 * Map a numeric cast level to the actor's spell-slot key (spell3, pact, …).
 * Mirrors dnd5e ActivityUsageDialog / _prepareUsageConfig slot selection.
 */
export function resolveSpellSlotKey(actor, item, castLevel) {
  const level = Math.floor(Number(castLevel));
  if (!Number.isFinite(level) || level < 1) return null;

  const spells = actor.system?.spells ?? {};
  const method = item.system?.method
    ?? resolveSpellCastingMethod(item.system);
  const model = CONFIG.DND5E?.spellcasting?.[method];

  if (model?.isSingleLevel && typeof model.getSpellSlotKey === "function") {
    const key = model.getSpellSlotKey(level);
    if (spells[key]) return key;
  }

  if (typeof model?.getSpellSlotKey === "function") {
    const key = model.getSpellSlotKey(level);
    if (spells[key] && (spells[key].level == null || spells[key].level === level)) {
      return key;
    }
  }

  const exact = `spell${level}`;
  if (spells[exact]) return exact;

  for (const [key, slot] of Object.entries(spells)) {
    if (!slot || typeof slot !== "object") continue;
    if ((slot.level ?? 0) === level && ((slot.max ?? 0) > 0 || (slot.value ?? 0) > 0)) {
      return key;
    }
  }

  return exact;
}

/**
 * Spends one charge of an item's limited uses, if it has any.
 *
 * dnd5e stores consumption as `uses.spent` against a derived `uses.max`, so the
 * update is on spent, never on the max — the max may be a formula.
 */
export async function spendItemUse(item) {
  const uses = item?.system?.uses;
  const max = Number(uses?.max);
  if (!Number.isFinite(max) || max <= 0) return false;
  const spent = Number(uses?.spent ?? 0);
  if (spent >= max) throw new Error(`${item.name}: no uses left`);
  await item.update({ "system.uses.spent": Math.min(max, spent + 1) });
  return true;
}

/** Sets remaining uses directly, for the counter on the feature card. */
export async function actorItemUsesSet(user, actorId, itemId, remainingRaw) {
  if (!itemId) throw new Error("itemId is required");
  const actor = getOwnedActor(user, actorId);
  const item = actor.items.get(itemId);
  if (!item) throw new Error("Item not found on actor");
  const max = Number(item.system?.uses?.max);
  if (!Number.isFinite(max) || max <= 0) throw new Error(`${item.name} has no limited uses`);
  const remaining = Math.max(0, Math.min(max, Math.floor(Number(remainingRaw))));
  if (!Number.isFinite(remaining)) throw new Error("remaining must be a number");
  await item.update({ "system.uses.spent": max - remaining });
  return {
    accepted: true,
    itemId: item.id,
    name: item.name,
    usesValue: remaining,
    usesMax: max
  };
}

/**
 * Activities a player can pick between when using an item.
 *
 * Foundry asks with a dialog on whichever tab runs the use — the GM's — and
 * blocks there until someone answers, which from the phone looks like a hang.
 * The list travels to the client instead, and the chosen id comes back.
 */
export function itemActivityChoices(item) {
  const out = [];
  for (const act of iterItemActivities(item?.system)) {
    if (act?.canUse === false) continue;
    const id = String(act?.id ?? act?._id ?? "");
    if (!id) continue;
    // Per-activity area, not the item's: on a spell whose first activity is an
    // attack and whose second is an area save, the item-level answer would send
    // the player to "use" and land the blast on themselves.
    const area = resolveTargetBlockTemplate(act?.target);
    const spec = area ? buildTemplateSpec(area.type, area.size) : null;
    out.push({
      id,
      name: String(act?.name ?? act?.label ?? item?.name ?? ""),
      activationType: String(act?.activation?.type ?? act?.type ?? ""),
      actionType: String(act?.type ?? ""),
      templateShape: spec?.shape ?? null,
      templateSize: spec?.size ?? null,
      img: routeAssetPath(act?.img ?? item?.img ?? null)
    });
  }
  return out;
}

/**
 * Token id of the caster when this use should auto-target the caster, else null.
 *
 * Activity being used: the chosen one; otherwise the single usable activity (more than
 * one without a choice has already returned needsActivityChoice); otherwise none.
 * Token rule: tokens of this actor on the ACTIVE scene (linked tokens by actorId, an
 * unlinked synthetic actor by its own token), preferring a combatant of the current
 * combat, else the first in scene order — same "first token" convention the template
 * code uses (tokenDocumentsForActorOnScene()[0]).
 */
export function resolveSelfRangeCasterTokenId(item, actor, chosenActivity, choices) {
  if (!canvas?.ready || !canvas.scene) return null;
  let used = chosenActivity ?? null;
  if (!used && choices?.length === 1) {
    used = iterItemActivities(item.system).find((a) => String(a?.id ?? a?._id) === String(choices[0].id)) ?? null;
  }
  if (!isSelfRangeNoArea(item, used, resolveTargetBlockTemplate)) return null;

  const docs = tokenDocumentsForActorOnScene(actor, canvas.scene);
  const combatTokenIds = [...(game.combat?.combatants ?? [])].map((c) => c.tokenId).filter(Boolean);
  const caster = pickCasterToken(docs, combatTokenIds);
  if (!caster) {
    grantLog("useItem self-range: no caster token on active scene, targets unchanged", {
      item: item.name, actorId: actor.id, sceneId: canvas.scene.id
    });
    return null;
  }
  if (!resolveTokenPlaceable(caster)) return null;
  return caster.id;
}

/**
 * Make the caster the only target of `user`, mirrored onto the GM tab's game.user —
 * the set midi-qol actually reads (activityHelpers: game.user.targets). Uses the same
 * mechanism as setTokenTarget (applyUserTokenTargets + _onUpdateTokenTargets) rather than
 * Token#setTarget, which always acts on game.user and ignores the phone player's viewedScene.
 * Resolves once the GM target set verifiably contains only the caster (one
 * presentation-frame retry), so item.use() never starts before the target is in place.
 * Never throws.
 */
export async function applySelfRangeCasterTarget(user, item, tokenId) {
  try {
    const set = () => {
      applyUserTokenTargets(user, [tokenId]);
      game.user._onUpdateTokenTargets([tokenId]);
    };
    const inPlace = () => game.user.targets.size === 1 && [...game.user.targets][0]?.id === tokenId;
    set();
    if (!inPlace()) {
      await waitForPresentationFrames(1);
      set();
    }
    const applied = inPlace();
    grantLog("useItem self-range: caster auto-targeted", {
      item: item.name, user: user?.name, tokenId, applied
    });
    return applied;
  } catch (err) {
    console.warn(`[${MODULE_ID}] useItem: self-range auto-target failed, continuing without`, err);
    return false;
  }
}

export async function useItem(
  user, actorId, itemId, templateId, advantageMode, spellSlotLevel, activityId
) {
  if (!itemId) throw new Error("itemId is required");
  const actor = getOwnedActor(user, actorId);
  const item = actor.items.get(itemId);
  if (!item) throw new Error("Item not found on actor");
  if (typeof item.use !== "function") {
    throw new Error("item.use is not supported for this item/system");
  }
  // Never let Foundry raise its own chooser: it would open on the GM tab and
  // wait there while the phone sits on a spinner. Either the client already
  // picked, or it is told to pick.
  const choices = itemActivityChoices(item);
  const chosenActivity = activityId
    ? iterItemActivities(item.system).find((a) => String(a?.id ?? a?._id) === String(activityId))
    : null;
  if (activityId && !chosenActivity) {
    throw new Error(`Activity not found on ${item.name}`);
  }
  if (!chosenActivity && choices.length > 1) {
    return { needsActivityChoice: true, itemId: item.id, name: item.name, activities: choices };
  }
  // An area activity fired without a template resolves on the caster — the
  // blast lands on the player who used it. Refuse and ask for aiming instead.
  // This has to live here, not in the client: an item may have a remembered
  // default, or a single activity, and neither path passes through a chooser.
  if (!templateId) {
    const aimed = chosenActivity ?? iterItemActivities(item.system)[0] ?? null;
    const area = resolveTargetBlockTemplate(aimed?.target);
    if (area) {
      const spec = buildTemplateSpec(area.type, area.size);
      return {
        needsTemplate: true,
        itemId: item.id,
        name: item.name,
        activityId: aimed?.id ?? aimed?._id ?? null,
        templateShape: spec.shape,
        templateSize: spec.size
      };
    }
  }
  grantLog("useItem", {
    user: user?.name,
    actorId,
    itemId,
    advantageMode,
    spellSlotLevel: spellSlotLevel ?? null,
    templateId: templateId || null,
    item: summarizeGrantItem(item, "useTarget")
  });

  const measuredSpec = itemMeasuredTemplateSpec(item);

  let savedDrawPreview = null;
  let savedTemplatePlacement = null;

  let existingTemplate = null;
  if (templateId && canvas?.scene) {
    existingTemplate = canvas.scene.templates.get(templateId) ?? null;
    if (!existingTemplate) {
      console.warn(`[${MODULE_ID}] useItem: client templateId not on scene (stale or wrong scene?)`, {
        templateId,
        sceneTemplateIds: canvas.scene.templates?.size ?? 0
      });
    }
  }

  const areaActivity = resolveItemAreaActivity(item);

  if (!existingTemplate && canvas?.scene && measuredSpec) {
    try {
      savedTemplatePlacement = resolveTemplatePlacementAtCasterToken(user, actor, measuredSpec);
    } catch (e) {
      console.warn(`[${MODULE_ID}] useItem: could not resolve template placement from caster token`, e);
    }
  }

  if (existingTemplate) {
    const workingTemplate = await finalizeStagedTemplatePlaceable(existingTemplate);
    savedTemplatePlacement = {
      t: workingTemplate.t,
      x: workingTemplate.x,
      y: workingTemplate.y,
      direction: workingTemplate.direction ?? 0,
      elevation: workingTemplate.elevation ?? 0,
      // Grid-correct: the v14 compat `distance` is off by sceneGridSize/100, and
      // this value is fed back into a new template.
      distance: templateGeometry(workingTemplate, regionForTemplate(workingTemplate, workingTemplate.parent ?? canvas.scene), canvas.grid).distance,
      fillColor: workingTemplate.fillColor ?? user.color ?? "#FF0000",
      reuseTemplateId: workingTemplate.id
    };
  }

  if (savedTemplatePlacement) {
    const proto = dnd5e.canvas.AbilityTemplate?.prototype;
    if (!proto || typeof proto.drawPreview !== "function") {
      console.error(`[${MODULE_ID}] useItem: dnd5e.canvas.AbilityTemplate.prototype.drawPreview missing`, {
        reuseTemplateId: savedTemplatePlacement.reuseTemplateId ?? null,
        AbilityTemplate: typeof dnd5e?.canvas?.AbilityTemplate
      });
    } else {
      savedDrawPreview = proto.drawPreview;
      const placement = savedTemplatePlacement;
      proto.drawPreview = async function() {
        const docBefore = this.document;

        let stagingFlags = null;
        if (placement.reuseTemplateId) {
          const reuseId = placement.reuseTemplateId;
          if (canvas.scene.templates.has(reuseId)) {
            const stagingDoc = canvas.scene.templates.get(reuseId);
            stagingFlags = foundry.utils.deepClone(stagingDoc.toObject()?.flags ?? {});
            await canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", [reuseId]);
            await waitForPresentationFrames(2);
          }
        }

        docBefore.updateSource({
          t: placement.t ?? docBefore.t,
          x: placement.x,
          y: placement.y,
          direction: placement.direction,
          elevation: placement.elevation,
          distance: placement.distance ?? docBefore.distance,
          fillColor: placement.fillColor ?? docBefore.fillColor,
          author: game.user.id
        });
        const docData = docBefore.toObject(false);
        docData.t = placement.t ?? docData.t;
        docData.x = placement.x;
        docData.y = placement.y;
        docData.direction = placement.direction;
        docData.elevation = placement.elevation;
        if (placement.distance != null) docData.distance = placement.distance;
        docData.author = game.user.id;
        if (docData.t === "cone" && docData.angle == null) {
          docData.angle = CONFIG?.MeasuredTemplate?.defaults?.angle ?? 53.13;
        }
        if (stagingFlags) {
          if (stagingFlags.dnd5e?.origin) {
            delete stagingFlags.dnd5e.origin;
            if (stagingFlags.dnd5e.dimensions) delete stagingFlags.dnd5e.dimensions;
          }
          docData.flags = foundry.utils.mergeObject(stagingFlags, docData.flags ?? {}, { inplace: false });
        }
        applyCastTemplateFlags(
          docData,
          areaActivity ?? this.activity,
          actor,
          tokenDocumentsForActorOnScene(actor, canvas.scene)[0],
          item
        );

        const createdList = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [docData]);
        const mqol = midiQolApi();
        if (mqol?.selectTargetsFromTemplates && createdList?.length) {
          const finalized = await finalizeStagedTemplatePlaceable(createdList[0]);
          const { ignoreSelf, aoEType, autoTarget } = midiAoETargetParams(areaActivity);
          const sourceToken = tokenDocumentsForActorOnScene(actor, canvas.scene)[0]?.object ?? null;
          const templateRef = finalized.object ?? finalized;
          mqol.selectTargetsFromTemplates(
            [templateRef],
            sourceToken,
            ignoreSelf,
            aoEType,
            autoTarget
          );
          // Derive the targeted token ids directly from the template rather than
          // reading game.user.targets: selectTargetsFromTemplates applies the
          // target rings asynchronously (via a hook), so game.user.targets is
          // still empty in this same tick — which left rememberTemplateTargets
          // recording [] and the 15s auto-remove with nothing to un-set.
          let appliedIds = [];
          if (typeof mqol.computeTargetsFromTemplates === "function") {
            appliedIds = mqol
              .computeTargetsFromTemplates([templateRef], sourceToken, ignoreSelf, aoEType, autoTarget)
              .map((t) => t.id)
              .filter(Boolean);
          } else {
            appliedIds = [...game.user.targets].map((t) => t.id);
          }
          applyUserTokenTargets(user, appliedIds);
          // Casting bypasses syncTemplateTargetsViaMidiQol (it targets via
          // selectTargetsFromTemplates, not computeTargetsFromTemplates), so the
          // record used by removeTemplate/removeTemplatesForItem at removal time
          // has to be written here too — otherwise it still holds whatever the
          // staging template last recorded (or nothing, if the cast never went
          // through a staging template), and the cast's real targets never get
          // un-set.
          rememberTemplateTargets(finalized, appliedIds);
        }
        return createdList;
      };
    }
  }

  const gmTargetIds = [...game.user.targets].map(t => t.id);
  // Captured BEFORE any self-targeting below: this is what gets restored.
  const playerTargetIds = mobileUserTargetIds(user);

  // Self-range, no-area items (Shield, Second Wind, Rage...) never ask the phone for
  // a target: the caster is the target. Area-from-caster spells (Burning Hands) are
  // excluded by isSelfRangeNoArea and keep the template flow. No token on the active
  // scene -> proceed exactly as before.
  const selfTargetTokenId = templateId
    ? null
    : resolveSelfRangeCasterTokenId(item, actor, chosenActivity, choices);

  const restoreGmTargets = () => {
    game.user._onUpdateTokenTargets(gmTargetIds);
  };
  const restorePlayerTargets = () => {
    applyUserTokenTargets(user, playerTargetIds);
  };
  const restoreAllTargets = () => {
    restoreGmTargets();
    restorePlayerTargets();
  };

  let selfTargetApplied = false;
  if (selfTargetTokenId) {
    selfTargetApplied = await applySelfRangeCasterTarget(user, item, selfTargetTokenId);
  }
  if (!selfTargetApplied && !savedDrawPreview) {
    game.user._onUpdateTokenTargets(playerTargetIds);
  }

  Hooks.once("midi-qol.RollComplete", () => {
    restoreAllTargets();
  });

  const normalizedMode = normalizeAdvantageMode(advantageMode);
  bridgeRuntimeState().lastMobileItemUse = {
    at: Date.now(),
    userId: user.id,
    actorId,
    advantageMode: normalizedMode
  };
  beginItemUseAdvantageMode(advantageMode);
  const itemUseConfig = buildItemUseRollConfig(advantageMode);
  const slotKey = item.type === "spell"
    ? resolveSpellSlotKey(actor, item, spellSlotLevel)
    : null;
  if (slotKey) {
    itemUseConfig.spell = { slot: slotKey };
    const slotLevel = actor.system?.spells?.[slotKey]?.level;
    const baseLevel = item.system?.level ?? 0;
    if (Number.isFinite(slotLevel) && slotLevel > baseLevel) {
      itemUseConfig.scaling = slotLevel - baseLevel;
    }
  }
  const itemUseDialog = {
    configure: false,
    configureDialog: false,
    event: itemUseConfig.event
  };
  rollAdvantageTrace("useItem roll config", {
    actorId,
    itemId,
    advantageMode: normalizedMode,
    spellSlotLevel: spellSlotLevel ?? null,
    spellSlotKey: slotKey,
    config: summarizeRollConfig(itemUseConfig)
  });

  beginItemCastSession(item);
  try {
    assertSpellSlotAvailable(actor, item, slotKey);
    // A chosen activity is used directly; Item5e#use would re-open the chooser.
    const usageResult = chosenActivity
      ? await chosenActivity.use(itemUseConfig, itemUseDialog, { create: true })
      : await item.use(itemUseConfig, itemUseDialog, { create: true });
    // An item with no activities never reaches an activity's consumption step:
    // Item5e#use just posts the card. Features imported without activities —
    // Bardic Inspiration, Invisibility — still have a charge to spend, so spend
    // it here. With activities present the activity already did it.
    if (usageResult != null && !iterItemActivities(item.system).length) {
      await spendItemUse(item);
    }
    // dnd5e returns void when consumption fails (e.g. no slots) — it only shows a
    // Foundry notification and does not throw, so treat empty result as failure.
    if (usageResult == null) {
      if (spellConsumesSpellSlot(item)) {
        throw makeNoSpellSlotsError(actor, item, slotKey);
      }
      throw new Error(`${item.name}: use canceled or failed`);
    }
  } catch (err) {
    console.error(`[${MODULE_ID}] useItem: item.use threw`, err);
    restoreAllTargets();
    throw err;
  } finally {
    deferEndItemUseAdvantageMode();
    endItemCastSession();
    // With midi-qol the workflow outlives item.use(), so the caster stays targeted until
    // midi-qol.RollComplete (hooked above). Without midi-qol there is no such workflow:
    // dnd5e has already read the targets, so give the player's selection back now.
    if (selfTargetApplied && !midiQolApi()) restoreAllTargets();
    if (savedDrawPreview) {
      dnd5e.canvas.AbilityTemplate.prototype.drawPreview = savedDrawPreview;
    }
  }
}

/** Whether this spell's activities consume a leveled spell slot when cast. */
export function spellConsumesSpellSlot(item) {
  if (item?.type !== "spell") return false;
  if ((item.system?.level ?? 0) <= 0) return false;
  const method = item.system?.method ?? resolveSpellCastingMethod(item.system);
  if (!CONFIG.DND5E?.spellcasting?.[method]?.slots) return false;
  const activities = iterItemActivities(item.system);
  if (!activities.length) return true;
  return activities.some((act) => act?.consumption?.spellSlot !== false);
}

/** Machine-readable no-slots error; Android localizes from bridgeCode + bridgeDetail. */
export function makeNoSpellSlotsError(actor, item, slotKey) {
  const key = slotKey
    ?? resolveSpellSlotKey(actor, item, item.system?.level);
  const slot = key ? actor.system?.spells?.[key] : null;
  const err = new Error("NO_SPELL_SLOTS");
  err.bridgeCode = "NO_SPELL_SLOTS";
  err.bridgeDetail = JSON.stringify({
    spellName: item?.name ?? "",
    slotKey: key ?? "",
    slotLevel: Number(slot?.level ?? item?.system?.level ?? 0) || 0
  });
  return err;
}

export function assertSpellSlotAvailable(actor, item, slotKey) {
  if (!spellConsumesSpellSlot(item)) return;
  const key = slotKey
    ?? resolveSpellSlotKey(actor, item, item.system?.level);
  if (!key) return;
  const slot = actor.system?.spells?.[key];
  if (!slot) return;
  if ((slot.value ?? 0) > 0) return;
  throw makeNoSpellSlotsError(actor, item, key);
}

// advantageMode: -1 = disadvantage, 0 = normal, 1 = advantage
export function normalizeAdvantageMode(raw) {
  const n = Number(raw);
  if (n === 1) return 1;
  if (n === -1) return -1;
  return 0;
}

export function applyAdvantageToRollConfig(config, advantageMode, context) {
  const mode = normalizeAdvantageMode(advantageMode);
  rollAdvantageTraceVerbose("applyAdvantageToRollConfig", {
    context: context ?? null,
    inputRaw: advantageMode,
    normalizedMode: mode,
    before: summarizeRollConfig(config)
  });
  if (mode === 1) {
    config.advantage = true;
    config.disadvantage = false;
  } else if (mode === -1) {
    config.advantage = false;
    config.disadvantage = true;
  } else {
    return mode;
  }
  // dnd5e v4 ability/save rolls merge advantage from rolls[0].options, not only top-level config.
  const opts = { advantage: config.advantage, disadvantage: config.disadvantage };
  config.rolls = [{ options: opts }, ...(Array.isArray(config.rolls) ? config.rolls : [])];
  rollAdvantageTraceVerbose("applyAdvantageToRollConfig result", {
    context: context ?? null,
    normalizedMode: mode,
    after: summarizeRollConfig(config)
  });
  if (mode !== 0) {
    rollAdvantageTrace("applyAdvantageToRollConfig", {
      context: context ?? null,
      mode,
      config: summarizeRollConfig(config)
    });
  }
  return mode;
}

// dnd5e v4 API uses { advantage: true/false, disadvantage: true/false } in config
export async function rollSkill(user, actorId, skillId, advantageMode) {
  if (!skillId) throw new Error("skillId is required");
  const actor = getOwnedActor(user, actorId);
  if (typeof actor.rollSkill !== "function") {
    throw new Error("rollSkill is not supported for this actor/system");
  }
  const config = { skill: skillId };
  const mode = applyAdvantageToRollConfig(config, advantageMode, "rollSkill");
  rollAdvantageTraceVerbose("rollSkill calling actor.rollSkill", {
    actorId,
    actorName: actor.name,
    skillId,
    mode,
    config: summarizeRollConfig(config)
  });
  await actor.rollSkill(config, { configure: false }, mobileRollMessageData(user));
  rollAdvantageTrace("rollSkill actor.rollSkill finished", { actorId, skillId, mode });
}

