export function buildHitDiceDto(actor) {
  const hd = actor.system?.attributes?.hd;
  if (!hd) return { value: 0, max: 0, bySize: [] };
  // hd.bySize is a plain object like { d8: 3, d10: 2 } in dnd5e v4
  const bySizeRaw = hd.bySize ?? {};
  const bySize = Object.entries(bySizeRaw)
    .map(([denomination, available]) => ({
      denomination,
      available: Number.isFinite(available) ? available : 0
    }))
    .filter(e => e.denomination)
    .sort((a, b) => a.denomination.localeCompare(b.denomination, "en", { numeric: true }));
  return {
    value: hd.value ?? 0,
    max: hd.max ?? 0,
    bySize
  };
}

export async function rollHitDie(user, actorId, denomination) {
  const actor = getOwnedActor(user, actorId);
  if (typeof actor.rollHitDie !== "function") {
    throw new Error("rollHitDie is not supported for this actor/system");
  }
  const config = {};
  if (denomination) config.denomination = denomination;
  await actor.rollHitDie(config, { configure: false }, mobileRollMessageData(user));
}

// Roll an arbitrary dice expression (dice tray / saved custom rolls). Uses the
// core Roll API rather than a dnd5e helper so any valid formula works; the
// "mobile" source flag routes the result back to the client via chat.roll.
export async function rollFormula(user, actorId, formula) {
  const expr = String(formula ?? "").trim();
  if (!expr) throw new Error("formula is required");
  const actor = getOwnedActor(user, actorId);
  if (!Roll.validate(expr)) {
    throw new Error(`invalid formula: ${expr}`);
  }
  const roll = new Roll(expr, actor.getRollData());
  await roll.evaluate();
  await roll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor }),
    flags: {
      [MODULE_ID]: {
        source: "mobile",
        userId: user.id
      }
    }
  });
}

