// Initiative roll. abilityId is optional — if provided, temporarily overrides
// actor.system.attributes.init.ability for this single roll without persisting.
// advantageMode: -1 = disadvantage, 0 = normal, 1 = advantage.
// Requires an active combat encounter; rollInitiative({createCombatants:true})
// adds the actor as combatant if needed and writes the rolled value to the
// combat tracker.
export async function rollInitiative(user, actorId, abilityId, advantageMode) {
  const actor = getOwnedActor(user, actorId);
  if (typeof actor.rollInitiative !== "function") {
    throw new Error("rollInitiative is not supported for this actor/system");
  }

  const combat = findStartedCombatForInitiative(actor);
  if (!combat) {
    throw new Error("Initiative roll requires an active combat encounter");
  }
  const active = await activateCombatForRoll(combat);
  if (!active) {
    throw new Error("Could not activate combat encounter for initiative roll");
  }

  const init = actor.system?.attributes?.init;
  const originalAbility = init?.ability ?? null;
  const wantOverride = !!(abilityId && init && abilityId !== originalAbility);

  const rollOptions = {};
  const mode = applyAdvantageToRollConfig(rollOptions, advantageMode, "rollInitiative");
  rollAdvantageTraceVerbose("rollInitiative calling actor.rollInitiative", {
    actorId,
    actorName: actor.name,
    abilityId,
    mode,
    config: summarizeRollConfig(rollOptions)
  });

  try {
    if (wantOverride) {
      init.ability = abilityId;
    }
    // dnd5e v4+: second arg configures the roll; first arg forwards to core Combat#rollInitiative.
    if (typeof actor.getInitiativeRoll === "function") {
      await actor.rollInitiative({ createCombatants: true }, rollOptions);
    } else {
      await actor.rollInitiative({ createCombatants: true });
    }
    rollAdvantageTrace("rollInitiative actor.rollInitiative finished", { actorId, mode });
  } finally {
    if (wantOverride) init.ability = originalAbility;
    delete actor._cachedInitiativeRoll;
  }
}

export async function rollAbility(user, actorId, abilityId, advantageMode) {
  if (!abilityId) throw new Error("abilityId is required");
  const actor = getOwnedActor(user, actorId);
  // dnd5e v4 uses rollAbilityCheck; older versions used rollAbilityTest.
  const fn = typeof actor.rollAbilityCheck === "function"
    ? actor.rollAbilityCheck.bind(actor)
    : (typeof actor.rollAbilityTest === "function" ? actor.rollAbilityTest.bind(actor) : null);
  if (!fn) {
    throw new Error("rollAbilityCheck is not supported for this actor/system");
  }
  const config = { ability: abilityId };
  const mode = applyAdvantageToRollConfig(config, advantageMode, "rollAbility");
  rollAdvantageTraceVerbose("rollAbility calling rollAbilityCheck", {
    actorId,
    actorName: actor.name,
    abilityId,
    mode,
    config: summarizeRollConfig(config)
  });
  await fn(config, { configure: false }, mobileRollMessageData(user));
  rollAdvantageTrace("rollAbility finished", { actorId, abilityId, mode });
}

